);

// ============================================================
// СОБРАТЬ СМЫСЛОВЫЕ РАЗДЕЛЫ v1.3
// Code Node -> Run Once for All Items
// ============================================================

const items = $input.all();

function getPageNo(block) {
  const pageNo = block?.source?.page_no;
  return Number.isFinite(pageNo) ? pageNo : null;
}

function normalizeForDetection(text) {
  return String(text ?? '')
    .replace(/\u00A0/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function isBoldBlock(block) {
  const formatting = block?.formatting;

  if (!formatting) {
    return false;
  }

  if (formatting.bold === true) {
    return true;
  }

  if (Array.isArray(formatting)) {
    return formatting.some(
      item => item?.bold === true
    );
  }

  return false;
}

function sameGroupPath(a, b) {
  const aPath =
    Array.isArray(a?.group_path)
      ? a.group_path
      : [];

  const bPath =
    Array.isArray(b?.group_path)
      ? b.group_path
      : [];

  if (
    aPath.length === 0 ||
    bPath.length === 0 ||
    aPath.length !== bPath.length
  ) {
    return false;
  }

  return aPath.every(
    (value, index) =>
      value === bPath[index]
  );
}

function getLastSourceBlock(
  semanticBlock,
  blockById
) {
  const ids =
    Array.isArray(
      semanticBlock?.source_block_ids
    )
      ? semanticBlock.source_block_ids
      : [];

  if (ids.length === 0) {
    return null;
  }

  return (
    blockById.get(
      ids[ids.length - 1]
    ) ?? null
  );
}

function getTopSectionNumber(text) {
  const value =
    normalizeForDetection(text);

  let match =
    value.match(
      /^(\d{1,3})\.\s+\S/
    );

  if (match) {
    return match[1];
  }

  match =
    value.match(
      /^(?:статья|раздел|глава)\s+(\d{1,3})(?:[\s.:]|$)/i
    );

  return match
    ? match[1]
    : null;
}

function startsWithChildOfSection(
  text,
  sectionNumber
) {
  if (!sectionNumber) {
    return false;
  }

  const value =
    normalizeForDetection(text);

  const escaped =
    String(sectionNumber)
      .replace(
        /[.*+?^${}()|[\]\\]/g,
        '\\$&'
      );

  return new RegExp(
    `^${escaped}\\.\\d+(?:\\.\\d+)*\\.\\s*`
  ).test(value);
}

function getNumberedClauseInfo(text) {
  const value =
    normalizeForDetection(text);

  const match =
    value.match(
      /^(\d+(?:\.\d+)+)\.\s*/
    );

  if (!match) {
    return null;
  }

  const number =
    match[1];

  const parts =
    number
      .split('.')
      .map(part => Number(part));

  return {
    number,
    parts,
    depth:
      parts.length,
  };
}

function isNumberedClauseStart(text) {
  return (
    getNumberedClauseInfo(text) !==
    null
  );
}

function isChildClause(
  childInfo,
  parentInfo
) {
  if (
    !childInfo ||
    !parentInfo
  ) {
    return false;
  }

  const child =
    childInfo.parts;

  const parent =
    parentInfo.parts;

  if (
    child.length <=
    parent.length
  ) {
    return false;
  }

  for (
    let i = 0;
    i < parent.length;
    i++
  ) {
    if (
      child[i] !==
      parent[i]
    ) {
      return false;
    }
  }

  return true;
}


// ============================================================
// ОПРЕДЕЛЕНИЕ ЗАГОЛОВКОВ
// ============================================================

function classifyHeading(block) {
  if (
    block?.type !==
    'text'
  ) {
    return {
      kind: 'none',
      level: null,
    };
  }

  const text =
    normalizeForDetection(
      block?.text
    );

  if (!text) {
    return {
      kind: 'none',
      level: null,
    };
  }


  // Статья 1...
  // Раздел 2...
  // Глава 3...

  if (
    /^(статья|раздел|глава)\s+\d+[\s.:]/i
      .test(text)
  ) {
    return {
      kind: 'section',
      level: 1,
      reason:
        'named_numbered_section',
    };
  }


  // Приложение № 4...

  if (
    /^приложение\s+№?\s*\d+/i
      .test(text)
  ) {
    const looksLikeReference =
      /\s[-–—]\s/.test(text) ||
      /[;.]$/.test(text);

    const parserSaysHeading =
      block?.label ===
        'section_header' ||
      block?.label ===
        'page_header';

    const visuallyHeading =
      isBoldBlock(block);

    if (
      !looksLikeReference &&
      (
        parserSaysHeading ||
        visuallyHeading
      )
    ) {
      return {
        kind: 'section',
        level: 1,
        reason:
          'appendix_heading',
      };
    }
  }


  // 4. Место и условия поставки

  if (
    /^\d{1,3}\.\s+\S/
      .test(text)
  ) {
    const parserSaysHeading =
      block?.label ===
      'section_header';

    const visuallyHeading =
      isBoldBlock(block);

    if (
      parserSaysHeading ||
      visuallyHeading
    ) {
      return {
        kind: 'section',
        level: 1,
        reason:
          'numbered_section',
      };
    }
  }


  // 5.4. Поставщик обязан:

  if (
    isNumberedClauseStart(
      text
    ) &&
    /:\s*$/.test(text)
  ) {
    const clauseInfo =
      getNumberedClauseInfo(
        text
      );

    return {
      kind: 'subsection',
      level: 2,
      reason:
        'numbered_lead_subheading',

      clause_number:
        clauseInfo?.number ??
        null,

      clause_depth:
        clauseInfo?.depth ??
        null,
    };
  }


  // Короткий ненумерованный heading от Docling

  if (
    block?.label ===
      'section_header' &&
    text.length <= 140 &&
    !/^\d+(?:\.\d+)+\.\s*/
      .test(text)
  ) {
    return {
      kind: 'subsection',
      level: 2,
      reason:
        'parser_subheading',
    };
  }


  return {
    kind: 'none',
    level: null,
  };
}


// ============================================================
// XLSX / ТАБЛИЦЫ:
// УМНОЕ ТЕКСТОВОЕ ПРЕДСТАВЛЕНИЕ
//
// Цель:
//
// 1. Простые строки из объединённых ячеек:
//
//    | РАСЧЕТ НМЦК | пусто | пусто | пусто | ...
//
//    превращаем просто в:
//
//    РАСЧЕТ НМЦК
//
//
// 2. Сложные таблицы НЕ сжимаем простым удалением
//    пустых колонок.
//
//    Вместо этого сохраняем координаты:
//
//    [C1] №
//    [C2-C3] Наименование товара
//    [C4] ОКПД2
//
//    Благодаря этому модель видит,
//    какой столбец к какому значению относится.
//
//
// 3. Row span тоже сохраняем:
//
//    [R5-R6,C1] №
//
//    означает:
//    ячейка занимает строки 5-6 и колонку 1.
//
//
// 4. Исходная структура table.cells при этом
//    вообще не изменяется.
//    Мы строим только удобный analysis-text.
// ============================================================


// ------------------------------------------------------------
// НОРМАЛИЗАЦИЯ ТЕКСТА ЯЧЕЙКИ
//
// В отличие от normalizeForDetection(),
// здесь сохраняем реальные переносы строк внутри ячейки.
// ------------------------------------------------------------

function normalizeTableCellText(text) {

  return String(text ?? '')
    .replace(/\u00A0/g, ' ')
    .split('\n')
    .map(
      line =>
        line
          .replace(/[ \t]+/g, ' ')
          .trim()
    )
    .filter(Boolean)
    .join('\n')
    .trim();
}


// ------------------------------------------------------------
// ТОЛЬКО НЕПУСТЫЕ ЯЧЕЙКИ
// ------------------------------------------------------------

function getNonEmptyTableCells(table) {

  const cells =
    Array.isArray(
      table?.cells
    )
      ? table.cells
      : [];


  return cells.filter(
    cell =>
      normalizeForDetection(
        cell?.text
      ).length > 0
  );
}


// ------------------------------------------------------------
// ШИРИНА ЯЧЕЙКИ В КОЛОНКАХ
// ------------------------------------------------------------

function getCellColSpan(cell) {

  if (
    Number.isFinite(
      cell?.col_span
    ) &&
    cell.col_span > 0
  ) {

    return cell.col_span;
  }


  if (
    Number.isFinite(
      cell?.col_start
    ) &&
    Number.isFinite(
      cell?.col_end
    )
  ) {

    return Math.max(
      1,
      cell.col_end -
      cell.col_start
    );
  }


  return 1;
}


// ------------------------------------------------------------
// ВЫСОТА ЯЧЕЙКИ В СТРОКАХ
// ------------------------------------------------------------

function getCellRowSpan(cell) {

  if (
    Number.isFinite(
      cell?.row_span
    ) &&
    cell.row_span > 0
  ) {

    return cell.row_span;
  }


  if (
    Number.isFinite(
      cell?.row_start
    ) &&
    Number.isFinite(
      cell?.row_end
    )
  ) {

    return Math.max(
      1,
      cell.row_end -
      cell.row_start
    );
  }


  return 1;
}


// ============================================================
// ОПРЕДЕЛЯЕМ:
// ЯВЛЯЕТСЯ ЛИ "ТАБЛИЦА" НА САМОМ ДЕЛЕ
// НАБОРОМ ОБЪЕДИНЁННЫХ ТЕКСТОВЫХ СТРОК
//
// Примеры:
//
// Заголовок листа
//
// РАСЧЕТ НМЦК
//
// Дата подготовки...
//
// Работник контрактной службы...
// Специалист по закупкам
// Оленева С.А.
//
// Для таких элементов координаты модели не нужны.
// ============================================================

function looksLikeLinearMergedTextTable(
  table
) {

  const numCols =
    Number.isFinite(
      table?.num_cols
    )
      ? table.num_cols
      : null;


  if (
    !numCols ||
    numCols <= 0
  ) {

    return false;
  }


  const cells =
    getNonEmptyTableCells(
      table
    );


  if (
    cells.length === 0
  ) {

    return false;
  }


  // ----------------------------------------------------------
  // Группируем ячейки по строкам,
  // в которых они НАЧИНАЮТСЯ.
  // ----------------------------------------------------------

  const rows =
    new Map();


  for (
    const cell
    of cells
  ) {

    const rowStart =
      Number.isFinite(
        cell?.row_start
      )
        ? cell.row_start
        : 0;


    if (
      !rows.has(
        rowStart
      )
    ) {

      rows.set(
        rowStart,
        []
      );
    }


    rows
      .get(rowStart)
      .push(cell);
  }


  // ----------------------------------------------------------
  // Чтобы считать элемент простым текстовым блоком:
  //
  // - в каждой содержательной строке
  //   должна быть ровно одна ячейка;
  //
  // - эта ячейка должна занимать минимум
  //   75% ширины таблицы.
  //
  // Это достаточно консервативное правило.
  // ----------------------------------------------------------

  for (
    const rowCells
    of rows.values()
  ) {

    if (
      rowCells.length !== 1
    ) {

      return false;
    }


    const cell =
      rowCells[0];


    const widthRatio =
      getCellColSpan(
        cell
      ) /
      numCols;


    if (
      widthRatio < 0.75
    ) {

      return false;
    }
  }


  return true;
}


// ============================================================
// ПРОСТАЯ "ТАБЛИЦА-ТЕКСТ"
//
// Никаких пустых разделителей.
//
// Было:
//
// Дата подготовки... | | | | | |
//
// Станет:
//
// Дата подготовки...
// ============================================================

function renderLinearMergedTextTable(
  table
) {

  const cells =
    getNonEmptyTableCells(
      table
    )
      .sort(
        (a, b) => {

          const rowDiff =
            (
              a?.row_start ??
              0
            ) -
            (
              b?.row_start ??
              0
            );


          if (
            rowDiff !== 0
          ) {

            return rowDiff;
          }


          return (
            (
              a?.col_start ??
              0
            ) -
            (
              b?.col_start ??
              0
            )
          );
        }
      );


  return cells
    .map(
      cell =>
        normalizeTableCellText(
          cell?.text
        )
    )
    .filter(Boolean)
    .join('\n');
}


// ============================================================
// КООРДИНАТА КОЛОНКИ
//
// col_start = 0
// col_end   = 1
//
// → C1
//
//
// col_start = 1
// col_end   = 3
//
// → C2-C3
// ============================================================

function formatColumnRange(
  cell
) {

  const colStart =
    Number.isFinite(
      cell?.col_start
    )
      ? cell.col_start + 1
      : 1;


  const colSpan =
    getCellColSpan(
      cell
    );


  const colEnd =
    colStart +
    colSpan -
    1;


  return (
    colStart === colEnd

      ? `C${colStart}`

      : `C${colStart}-C${colEnd}`
  );
}


// ============================================================
// КООРДИНАТА СТРОКИ
//
// row_start = 4
// row_end   = 6
//
// → R5-R6
// ============================================================

function formatRowRange(
  cell
) {

  const rowStart =
    Number.isFinite(
      cell?.row_start
    )
      ? cell.row_start + 1
      : 1;


  const rowSpan =
    getCellRowSpan(
      cell
    );


  const rowEnd =
    rowStart +
    rowSpan -
    1;


  return (
    rowStart === rowEnd

      ? `R${rowStart}`

      : `R${rowStart}-R${rowEnd}`
  );
}


// ============================================================
// СЛОЖНАЯ ТАБЛИЦА
//
// Пример результата:
//
// ТАБЛИЦА
// Координаты: R = строка, C = колонка.
//
// Строка R5:
// [R5-R6,C1] №
// [R5-R6,C2-C3] Наименование товара
// [R5-R6,C4] ОКПД2
// [C7] Поставщик 1
//
// Строка R6:
// [C7] Цена (руб.)
//
// Строка R7:
// [C1] 1
// [C2-C3] Судовые журналы...
// [C4] 17.23.13.110
// [C7] 449,00
//
// Это позволяет модели точно связать:
//
// C7 = Поставщик 1
// C7 = 449,00
// ============================================================

function renderCoordinateTable(
  table
) {

  const cells =
    getNonEmptyTableCells(
      table
    )
      .sort(
        (a, b) => {

          const rowDiff =
            (
              a?.row_start ??
              0
            ) -
            (
              b?.row_start ??
              0
            );


          if (
            rowDiff !== 0
          ) {

            return rowDiff;
          }


          return (
            (
              a?.col_start ??
              0
            ) -
            (
              b?.col_start ??
              0
            )
          );
        }
      );


  if (
    cells.length === 0
  ) {

    return (
      '[Таблица без текстовых значений]'
    );
  }


  // ----------------------------------------------------------
  // Группируем ячейки по строкам,
  // где каждая ячейка начинается.
  // ----------------------------------------------------------

  const rows =
    new Map();


  for (
    const cell
    of cells
  ) {

    const rowStart =
      Number.isFinite(
        cell?.row_start
      )
        ? cell.row_start
        : 0;


    if (
      !rows.has(
        rowStart
      )
    ) {

      rows.set(
        rowStart,
        []
      );
    }


    rows
      .get(rowStart)
      .push(cell);
  }


  const lines = [

    'ТАБЛИЦА',

    'Координаты: R = строка, C = колонка.',
  ];


  const orderedRows =
    [
      ...rows.entries(),
    ]
      .sort(
        (a, b) =>
          a[0] -
          b[0]
      );


  for (
    const [
      rowStart,
      rowCells
    ]
    of orderedRows
  ) {

    lines.push('');


    lines.push(
      `Строка R${rowStart + 1}:`
    );


    for (
      const cell
      of rowCells
    ) {

      const text =
        normalizeTableCellText(
          cell?.text
        );


      if (!text) {
        continue;
      }


      const columnRange =
        formatColumnRange(
          cell
        );


      const rowRange =
        formatRowRange(
          cell
        );


      const rowSpan =
        getCellRowSpan(
          cell
        );


      // ------------------------------------------------------
      // Если ячейка занимает несколько строк,
      // обязательно показываем и R, и C.
      //
      // Если только одну строку —
      // номера текущей строки уже достаточно,
      // поэтому показываем только колонку.
      // ------------------------------------------------------

      const coordinate =
        rowSpan > 1

          ? `[${rowRange},${columnRange}]`

          : `[${columnRange}]`;


      // ------------------------------------------------------
      // Сохраняем переносы внутри самой ячейки.
      // ------------------------------------------------------

      const textLines =
        text.split('\n');


      lines.push(
        `${coordinate} ${textLines[0]}`
      );


      for (
        let i = 1;
        i < textLines.length;
        i++
      ) {

        lines.push(
          `  ${textLines[i]}`
        );
      }
    }
  }


  return lines
    .join('\n')
    .trim();
}


// ============================================================
// ГЛАВНЫЙ RENDERER ТАБЛИЦЫ
// ============================================================

function tableToText(block) {

  const table =
    block?.table;


  if (!table) {

    return '[Таблица]';
  }


  const cells =
    Array.isArray(
      table?.cells
    )
      ? table.cells
      : [];


  // ----------------------------------------------------------
  // FALLBACK:
  // если вдруг parser не дал table.cells,
  // используем старые rows.
  // ----------------------------------------------------------

  if (
    cells.length === 0
  ) {

    const rows =
      Array.isArray(
        table?.rows
      )
        ? table.rows
        : [];


    if (
      rows.length === 0
    ) {

      return '[Таблица]';
    }


    return rows
      .map(row => {

        const rowCells =
          Array.isArray(
            row?.cells
          )
            ? row.cells
            : [];


        return rowCells
          .map(
            cell =>
              normalizeTableCellText(
                cell?.text
              )
          )
          .filter(Boolean)
          .join(' | ');
      })
      .filter(Boolean)
      .join('\n');
  }


  // ----------------------------------------------------------
  // РЕЖИМ 1:
  //
  // широкие объединённые строки,
  // которые по сути являются обычным текстом.
  // ----------------------------------------------------------

  if (
    looksLikeLinearMergedTextTable(
      table
    )
  ) {

    return renderLinearMergedTextTable(
      table
    );
  }


  // ----------------------------------------------------------
  // РЕЖИМ 2:
  //
  // настоящая структурная таблица.
  // Используем координатное представление.
  // ----------------------------------------------------------

  return renderCoordinateTable(
    table
  );
}


// ============================================================
// НАЧАЛО НОВОЙ ЛОГИЧЕСКОЙ ЕДИНИЦЫ
// ============================================================

function startsNewLogicalUnit(
  block,
  preclassifiedHeading = null
) {
  if (!block) {
    return true;
  }

  if (
    block.type ===
    'table'
  ) {
    return true;
  }

  const heading =
    preclassifiedHeading ??
    classifyHeading(block);

  if (
    heading.kind !==
    'none'
  ) {
    return true;
  }

  const text =
    normalizeForDetection(
      block?.text
    );

  if (!text) {
    return false;
  }

  if (
    /^\d+(?:\.\d+)+\.\s*/
      .test(text)
  ) {
    return true;
  }

  if (
    /^\d{1,3}\.\s+\S/
      .test(text)
  ) {
    return true;
  }

  if (
    /^(статья|раздел|глава)\s+\d+/i
      .test(text)
  ) {
    return true;
  }

  if (
    /^приложение\s+№?\s*\d+/i
      .test(text)
  ) {
    return true;
  }

  return false;
}


function previousLooksIncomplete(
  block
) {
  if (
    !block ||
    block.type !==
    'text'
  ) {
    return false;
  }

  const text =
    normalizeForDetection(
      block?.text
    );

  if (!text) {
    return false;
  }

  if (
    /[.!?;:]$/.test(
      text
    )
  ) {
    return false;
  }

  return true;
}


function sourceRecord(block) {
  return {
    block_id:
      block.block_id,

    page_no:
      getPageNo(
        block
      ),

    bbox:
      block?.source?.bbox ??
      null,

    label:
      block?.label ??
      null,

    analysis_order:
      block?.analysis
        ?.analysis_order ??
      null,
  };
}


// ============================================================
// DOCX:
// СКЛЕИВАЕМ РАЗОРВАННЫЙ ЗАГОЛОВОК
// ============================================================

function mergeDocxSplitSectionHeadings(
  semanticBlocks,
  blockById,
  semanticCorrections
) {
  let mergedCount = 0;


  for (
    let i = 0;
    i <
      semanticBlocks.length -
        1;
    i++
  ) {
    const headingBlock =
      semanticBlocks[i];


    if (
      headingBlock?.role !==
      'section_heading'
    ) {
      continue;
    }


    const sectionNumber =
      getTopSectionNumber(
        headingBlock.text
      );

    if (!sectionNumber) {
      continue;
    }


    const headingSource =
      getLastSourceBlock(
        headingBlock,
        blockById
      );

    if (
      !headingSource ||
      !isBoldBlock(
        headingSource
      )
    ) {
      continue;
    }


    if (
      /[.!?;:]$/.test(
        normalizeForDetection(
          headingBlock.text
        )
      )
    ) {
      continue;
    }


    const continuationBlocks =
      [];

    let nextIndex =
      i + 1;


    while (
      nextIndex <
        semanticBlocks.length &&
      continuationBlocks.length <
        3
    ) {
      const candidate =
        semanticBlocks[
          nextIndex
        ];


      const candidateCanBeContinuation =
        candidate?.type ===
          'text' &&
        (
          candidate?.role ===
            'paragraph' ||
          (
            candidate?.role ===
              'subsection_heading' &&
            candidate
              ?.heading_detection
              ?.reason ===
              'parser_subheading'
          )
        );


      if (
        !candidateCanBeContinuation
      ) {
        break;
      }


      const candidateSource =
        getLastSourceBlock(
          candidate,
          blockById
        );


      const candidateText =
        normalizeForDetection(
          candidate.text
        );


      if (
        !candidateSource ||
        !candidateText ||
        candidateText.length >
          160 ||
        /^\d/.test(
          candidateText
        ) ||
        !isBoldBlock(
          candidateSource
        ) ||
        !sameGroupPath(
          headingSource,
          candidateSource
        )
      ) {
        break;
      }


      continuationBlocks.push(
        candidate
      );

      nextIndex++;
    }


    if (
      continuationBlocks.length ===
      0
    ) {
      continue;
    }


    const followingBlock =
      semanticBlocks[
        nextIndex
      ];


    if (
      !followingBlock ||
      !startsWithChildOfSection(
        followingBlock.text,
        sectionNumber
      )
    ) {
      continue;
    }


    const continuationText =
      continuationBlocks
        .map(
          block =>
            normalizeForDetection(
              block.text
            )
        )
        .join(' ');


    headingBlock.text =
      `${
        normalizeForDetection(
          headingBlock.text
        )
      } ${continuationText}`
        .trim();


    for (
      const continuation
      of continuationBlocks
    ) {
      headingBlock
        .source_block_ids
        .push(
          ...continuation
            .source_block_ids
        );


      headingBlock
        .sources
        .push(
          ...continuation
            .sources
        );


      headingBlock
        .source_pages =
        [
          ...new Set([
            ...headingBlock
              .source_pages,

            ...continuation
              .source_pages,
          ]),
        ];


      if (
        continuation.page_from !==
        null
      ) {
        headingBlock.page_from =
          headingBlock.page_from ===
          null
            ? continuation
                .page_from
            : Math.min(
                headingBlock
                  .page_from,
                continuation
                  .page_from
              );
      }


      if (
        continuation.page_to !==
        null
      ) {
        headingBlock.page_to =
          headingBlock.page_to ===
          null
            ? continuation
                .page_to
            : Math.max(
                headingBlock
                  .page_to,
                continuation
                  .page_to
              );
      }
    }


    headingBlock
      .merged_heading_continuation =
      true;


    semanticCorrections.push({
      type:
        'merged_split_section_heading',

      semantic_block_id:
        headingBlock
          .semantic_block_id,

      source_block_ids:
        [
          ...headingBlock
            .source_block_ids,
        ],

      merged_title:
        headingBlock.text,

      reason:
        'Последовательные жирные DOCX-блоки объединены в один заголовок и подтверждены следующим дочерним пунктом раздела.',
    });


    semanticBlocks.splice(
      i + 1,
      continuationBlocks.length
    );


    mergedCount++;
  }


  return mergedCount;
}


// ============================================================
// XLSX:
// СТРОИМ ПОСТОЯННЫЙ КОНТЕКСТ ЛИСТОВ
//
// Ищем в начале листа таблицу вида:
//
// одна строка
// одна содержательная объединённая ячейка
// ячейка занимает >= 50% ширины
//
// Такая таблица считается потенциальным заголовком листа.
// ============================================================

function buildXlsxSheetContexts(
  orderedBlocks,
  semanticBlocks
) {
  const semanticBySourceId =
    new Map();


  // Связываем исходный block_id
  // с semantic_block_id.

  for (
    const semanticBlock
    of semanticBlocks
  ) {
    const sourceIds =
      Array.isArray(
        semanticBlock
          ?.source_block_ids
      )
        ? semanticBlock
            .source_block_ids
        : [];


    for (
      const sourceId
      of sourceIds
    ) {
      semanticBySourceId.set(
        sourceId,
        semanticBlock
      );
    }
  }


  // Группируем блоки по листам Excel.

  const blocksBySheet =
    new Map();


  for (
    const block
    of orderedBlocks
  ) {
    const sheetName =
      String(
        block?.sheet_name ??
        ''
      ).trim();


    if (!sheetName) {
      continue;
    }


    if (
      !blocksBySheet.has(
        sheetName
      )
    ) {
      blocksBySheet.set(
        sheetName,
        []
      );
    }


    blocksBySheet
      .get(
        sheetName
      )
      .push(
        block
      );
  }


  const sheets = [];


  for (
    const [
      sheetName,
      sheetBlocks
    ]
    of blocksBySheet.entries()
  ) {
    const firstBlock =
      sheetBlocks[0] ??
      null;


    let sheetTitle =
      null;

    let titleSourceBlockId =
      null;

    let titleSemanticBlockId =
      null;

    let titleDetection =
      null;


    // --------------------------------------------------------
    // ПЕРВАЯ ТАБЛИЦА МОЖЕТ БЫТЬ ЗАГОЛОВКОМ
    // --------------------------------------------------------

    if (
      firstBlock?.type ===
      'table'
    ) {
      const table =
        firstBlock?.table;


      const cells =
        Array.isArray(
          table?.cells
        )
          ? table.cells
          : [];


      const nonEmptyCells =
        cells.filter(
          cell =>
            normalizeForDetection(
              cell?.text
            ).length > 0
        );


      const numRows =
        Number.isFinite(
          table?.num_rows
        )
          ? table.num_rows
          : null;


      const numCols =
        Number.isFinite(
          table?.num_cols
        )
          ? table.num_cols
          : null;


      if (
        numRows === 1 &&
        nonEmptyCells.length ===
          1
      ) {
        const cell =
          nonEmptyCells[0];


        const titleText =
          normalizeForDetection(
            cell?.text
          );


        const colSpan =
          Number.isFinite(
            cell?.col_span
          )
            ? cell.col_span
            : (
                Number.isFinite(
                  cell?.col_end
                ) &&
                Number.isFinite(
                  cell?.col_start
                )

                  ? (
                      cell.col_end -
                      cell.col_start
                    )

                  : 1
              );


        const widthRatio =
          numCols &&
          numCols > 0

            ? (
                colSpan /
                numCols
              )

            : 1;


        const looksLikeSheetTitle =
          titleText.length >=
            5 &&
          titleText.length <=
            300 &&
          widthRatio >=
            0.5;


        if (
          looksLikeSheetTitle
        ) {
          sheetTitle =
            titleText;


          titleSourceBlockId =
            firstBlock.block_id;


          titleSemanticBlockId =
            semanticBySourceId
              .get(
                firstBlock
                  .block_id
              )
              ?.semantic_block_id ??
            null;


          titleDetection =
            'leading_single_merged_cell_table';
        }
      }
    }


    sheets.push({
      sheet_name:
        sheetName,

      sheet_title:
        sheetTitle,

      title_source_block_id:
        titleSourceBlockId,

      title_semantic_block_id:
        titleSemanticBlockId,

      title_detection:
        titleDetection,

      source_blocks_count:
        sheetBlocks.length,
    });
  }


  return {
    sheets_count:
      sheets.length,

    sheets,
  };
}


// ============================================================
// ОБРАБОТКА ОДНОГО ДОКУМЕНТА
// ============================================================

function processDocument(input) {
  const sourceBlocks =
    Array.isArray(
      input.blocks
    )
      ? input.blocks
      : [];


  const blockById =
    new Map(
      sourceBlocks.map(
        block => [
          block.block_id,
          block,
        ]
      )
    );


  const warnings = [];


  // ==========================================================
  // ТИП ДОКУМЕНТА
  // ==========================================================

  const fileName =
    String(
      input?.document
        ?.file_name ??
      input?.parser
        ?.origin
        ?.filename ??
      ''
    ).trim();


  const mimeType =
    String(
      input?.document
        ?.mime_type ??
      input?.parser
        ?.origin
        ?.mimetype ??
      ''
    )
      .trim()
      .toLowerCase();


  let fileExtension =
    String(
      input?.document
        ?.file_extension ??
      ''
    )
      .trim()
      .toLowerCase()
      .replace(
        /^\./,
        ''
      );


  if (
    !fileExtension &&
    fileName.includes('.')
  ) {
    fileExtension =
      fileName
        .split('.')
        .pop()
        .trim()
        .toLowerCase();
  }


  const isDocx =
    fileExtension ===
      'docx' ||
    mimeType ===
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document';


  const isXlsx =
    fileExtension ===
      'xlsx' ||
    mimeType ===
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';


  // ==========================================================
  // АУДИТ КОРРЕКЦИЙ
  // ==========================================================

  const semanticCorrections =
    [];


  let downgradedParserSubheadingsCount =
    0;


  let mergedSplitSectionHeadingsCount =
    0;


  // ==========================================================
  // 1. ВОССТАНАВЛИВАЕМ ПОДГОТОВЛЕННЫЙ ПОРЯДОК
  // ==========================================================

  const orderedBlocks =
    [];


  const seenBlocks =
    new Set();


  const analysisSequence =
    Array.isArray(
      input.analysis_sequence
    )
      ? input
          .analysis_sequence
      : [];


  for (
    const blockId
    of analysisSequence
  ) {
    const block =
      blockById.get(
        blockId
      );


    if (!block) {
      warnings.push({
        type:
          'missing_analysis_sequence_block',

        block_id:
          blockId,

        message:
          'В analysis_sequence есть ссылка на отсутствующий блок.',
      });

      continue;
    }


    if (
      block?.analysis
        ?.include !==
      true
    ) {
      continue;
    }


    if (
      seenBlocks.has(
        blockId
      )
    ) {
      warnings.push({
        type:
          'duplicate_analysis_sequence_block',

        block_id:
          blockId,

        message:
          'Один блок встретился в analysis_sequence повторно.',
      });

      continue;
    }


    orderedBlocks.push(
      block
    );


    seenBlocks.add(
      blockId
    );
  }


  // Если include=true,
  // но блока нет в sequence,
  // всё равно сохраняем.

  const extraBlocks =
    sourceBlocks
      .filter(
        block =>
          block?.analysis
            ?.include ===
            true &&
          !seenBlocks.has(
            block.block_id
          )
      )
      .sort(
        (a, b) => {
          const aOrder =
            a?.analysis
              ?.analysis_order ??
            a?.order ??
            0;

          const bOrder =
            b?.analysis
              ?.analysis_order ??
            b?.order ??
            0;

          return (
            aOrder -
            bOrder
          );
        }
      );


  if (
    extraBlocks.length > 0
  ) {
    warnings.push({
      type:
        'included_blocks_missing_from_sequence',

      count:
        extraBlocks.length,

      block_ids:
        extraBlocks.map(
          block =>
            block.block_id
        ),

      message:
        'Есть включённые блоки, которых не было в analysis_sequence. Они сохранены отдельно.',
    });


    for (
      const block
      of extraBlocks
    ) {
      orderedBlocks.push(
        block
      );

      seenBlocks.add(
        block.block_id
      );
    }
  }


  // ==========================================================
  // 2. ПЕРВЫЙ / ПОСЛЕДНИЙ БЛОК СТРАНИЦЫ
  // ==========================================================

  const firstBlockByPage =
    new Map();


  const lastBlockByPage =
    new Map();


  for (
    const block
    of orderedBlocks
  ) {
    const pageNo =
      getPageNo(
        block
      );


    if (
      pageNo === null
    ) {
      continue;
    }


    if (
      !firstBlockByPage
        .has(
          pageNo
        )
    ) {
      firstBlockByPage.set(
        pageNo,
        block.block_id
      );
    }


    lastBlockByPage.set(
      pageNo,
      block.block_id
    );
  }


  // ==========================================================
  // 3. СОБИРАЕМ SEMANTIC BLOCKS
  // ==========================================================

  const semanticBlocks =
    [];


  let mergedContinuationsCount =
    0;


  for (
    const block
    of orderedBlocks
  ) {
    let heading =
      classifyHeading(
        block
      );


    const pageNo =
      getPageNo(
        block
      );


    const previousSemanticBlock =
      semanticBlocks.length >
        0

        ? semanticBlocks[
            semanticBlocks
              .length -
              1
          ]

        : null;


    const previousLastSourceId =
      previousSemanticBlock &&
      previousSemanticBlock
        .source_block_ids
        .length > 0

        ? previousSemanticBlock
            .source_block_ids[
              previousSemanticBlock
                .source_block_ids
                .length -
                1
            ]

        : null;


    const previousSourceBlock =
      previousLastSourceId

        ? blockById.get(
            previousLastSourceId
          )

        : null;


    // ========================================================
    // DOCX:
    // ПОНИЖАЕМ ЛОЖНЫЙ parser_subheading
    // ========================================================

    if (
      isDocx &&

      heading?.kind ===
        'subsection' &&

      heading?.reason ===
        'parser_subheading' &&

      previousSemanticBlock
        ?.type ===
        'text'
    ) {
      const previousText =
        normalizeForDetection(
          previousSemanticBlock
            .text
        );


      const currentText =
        normalizeForDetection(
          block.text
        );


      const previousIsNumberedClause =
        isNumberedClauseStart(
          previousText
        );


      const previousLooksOpen =
        previousText.length >
          0 &&
        !/[.!?;:]$/.test(
          previousText
        );


      const currentNotBold =
        !isBoldBlock(
          block
        );


      const currentLooksLikeContent =
        /[:;]/.test(
          currentText
        ) ||
        /[.!?]$/.test(
          currentText
        );


      const sameWordGroup =
        previousSourceBlock !==
          null &&
        sameGroupPath(
          previousSourceBlock,
          block
        );


      if (
        previousIsNumberedClause &&
        previousLooksOpen &&
        currentNotBold &&
        currentLooksLikeContent &&
        sameWordGroup
      ) {
        semanticCorrections.push({
          type:
            'downgraded_parser_subheading',

          block_id:
            block.block_id,

          text:
            currentText,

          previous_block_id:
            previousSourceBlock
              .block_id,

          reason:
            'DOCX parser_subheading выглядит продолжением предыдущего незаконченного нумерованного пункта.',
        });


        downgradedParserSubheadingsCount++;


        heading = {
          kind: 'none',
          level: null,
        };
      }
    }


    const previousPageNo =
      getPageNo(
        previousSourceBlock
      );


    const isFirstUsefulBlockOnPage =
      pageNo !== null &&
      firstBlockByPage
        .get(
          pageNo
        ) ===
        block.block_id;


    const previousWasLastUsefulBlockOnPage =
      previousPageNo !==
        null &&
      lastBlockByPage
        .get(
          previousPageNo
        ) ===
        previousLastSourceId;


    const pagesAreConsecutive =
      pageNo !== null &&
      previousPageNo !==
        null &&
      pageNo ===
        previousPageNo +
          1;


    const canMergeAcrossPage =
      previousSemanticBlock !==
        null &&

      previousSemanticBlock
        .type ===
        'text' &&

      previousSemanticBlock
        .role !==
        'section_heading' &&

      previousSemanticBlock
        .role !==
        'subsection_heading' &&

      block.type ===
        'text' &&

      heading.kind ===
        'none' &&

      pagesAreConsecutive &&

      isFirstUsefulBlockOnPage &&

      previousWasLastUsefulBlockOnPage &&

      previousLooksIncomplete(
        previousSourceBlock
      ) &&

      !startsNewLogicalUnit(
        block,
        heading
      );


    if (
      canMergeAcrossPage
    ) {
      previousSemanticBlock.text =
        `${
          String(
            previousSemanticBlock
              .text ??
            ''
          ).trim()
        } ${
          String(
            block.text ??
            ''
          ).trim()
        }`.trim();


      previousSemanticBlock
        .source_block_ids
        .push(
          block.block_id
        );


      previousSemanticBlock
        .sources
        .push(
          sourceRecord(
            block
          )
        );


      if (
        pageNo !== null &&
        !previousSemanticBlock
          .source_pages
          .includes(
            pageNo
          )
      ) {
        previousSemanticBlock
          .source_pages
          .push(
            pageNo
          );
      }


      previousSemanticBlock
        .page_to =
        pageNo;


      previousSemanticBlock
        .merged_across_pages =
        true;


      mergedContinuationsCount++;


      continue;
    }


    // ========================================================
    // НОВЫЙ SEMANTIC BLOCK
    // ========================================================

    let role =
      'paragraph';


    if (
      heading.kind ===
      'section'
    ) {
      role =
        'section_heading';
    }

    else if (
      heading.kind ===
      'subsection'
    ) {
      role =
        'subsection_heading';
    }

    else if (
      block.type ===
      'table'
    ) {
      role =
        'table';
    }


    const canonicalText =
      block.type === 'table'
        ? tableToText(
            block
          )
        : String(
            block.text ??
            ''
          );

    const blockOptionStates =
      Array.isArray(
        block?.docx_option_states
      )
        ? block.docx_option_states
        : [];

    const optionStateMarkers =
      blockOptionStates.map(
        optionState =>
          (
            '[OPTION_STATE ' +
            (
              optionState?.state ??
              'unknown'
            ) +
            '] ' +
            (
              optionState?.exact_label ??
              ''
            )
          ).trim()
      );

    const semanticBlock = {

      semantic_block_id:
        `sb_${String(
          semanticBlocks.length +
            1
        ).padStart(
          4,
          '0'
        )}`,

      type:
        block.type ===
          'table'

          ? 'table'

          : 'text',

      role,


      // ------------------------------------------------------
      // XLSX:
      // сохраняем имя листа.
      // ------------------------------------------------------

      sheet_name:
        block?.sheet_name ??
        null,


      text:
        canonicalText,

      ai_text:
        optionStateMarkers.length > 0
          ? [
              canonicalText,
              ...optionStateMarkers,
            ].join('\n')
          : canonicalText,

      docx_option_states:
        blockOptionStates,

      option_state_markers:
        optionStateMarkers,


      source_block_ids: [
        block.block_id,
      ],


      source_pages:
        pageNo === null

          ? []

          : [
              pageNo,
            ],


      page_from:
        pageNo,

      page_to:
        pageNo,


      merged_across_pages:
        false,


      heading_detection:
        heading.kind ===
          'none'

          ? null

          : {
              level:
                heading.level,

              reason:
                heading.reason,

              clause_number:
                heading
                  .clause_number ??
                null,

              clause_depth:
                heading
                  .clause_depth ??
                null,
            },


      sources: [
        sourceRecord(
          block
        ),
      ],
    };


    semanticBlocks.push(
      semanticBlock
    );
  }


  // ==========================================================
  // 3.1 DOCX:
  // СКЛЕИВАЕМ РАЗОРВАННЫЕ ЗАГОЛОВКИ
  // ==========================================================

  if (
    isDocx
  ) {
    mergedSplitSectionHeadingsCount =
      mergeDocxSplitSectionHeadings(
        semanticBlocks,
        blockById,
        semanticCorrections
      );
  }


  // ==========================================================
  // 3.2 XLSX:
  // ПОСТОЯННЫЙ КОНТЕКСТ ЛИСТОВ
  // ==========================================================

  const spreadsheetContext =
    isXlsx

      ? buildXlsxSheetContexts(
          orderedBlocks,
          semanticBlocks
        )

      : null;


  // ==========================================================
  // 4. СОБИРАЕМ SECTIONS
  // ==========================================================

  const sections =
    [];


  let currentSection =
    null;


  let currentSubheading =
    null;


  function startSection(
    title,
    kind,
    headingSemanticBlock =
      null
  ) {
    const section = {

      section_id:
        `sec_${String(
          sections.length +
            1
        ).padStart(
          3,
          '0'
        )}`,

      title,

      kind,

      semantic_block_ids:
        [],

      source_block_ids:
        [],

      page_from:
        null,

      page_to:
        null,

      text_characters:
        0,

      tables_count:
        0,
    };


    sections.push(
      section
    );


    currentSection =
      section;


    currentSubheading =
      null;


    if (
      headingSemanticBlock
    ) {
      addToCurrentSection(
        headingSemanticBlock
      );
    }


    return section;
  }


  function addToCurrentSection(
    semanticBlock
  ) {
    if (
      !currentSection
    ) {
      startSection(
        'Преамбула',
        'preamble'
      );
    }


    currentSection
      .semantic_block_ids
      .push(
        semanticBlock
          .semantic_block_id
      );


    currentSection
      .source_block_ids
      .push(
        ...semanticBlock
          .source_block_ids
      );


    if (
      semanticBlock.page_from !==
      null
    ) {
      currentSection.page_from =
        currentSection
          .page_from ===
        null

          ? semanticBlock
              .page_from

          : Math.min(
              currentSection
                .page_from,
              semanticBlock
                .page_from
            );
    }


    if (
      semanticBlock.page_to !==
      null
    ) {
      currentSection.page_to =
        currentSection
          .page_to ===
        null

          ? semanticBlock
              .page_to

          : Math.max(
              currentSection
                .page_to,
              semanticBlock
                .page_to
            );
    }


    currentSection
      .text_characters +=
      String(
        semanticBlock.text ??
        ''
      ).length;


    if (
      semanticBlock.type ===
      'table'
    ) {
      currentSection
        .tables_count++;
    }


    semanticBlock
      .section_id =
      currentSection
        .section_id;


    semanticBlock
      .section_title =
      currentSection
        .title;


    semanticBlock
      .section_path =
      currentSubheading

        ? [
            currentSection
              .title,

            currentSubheading
              .title,
          ]

        : [
            currentSection
              .title,
          ];
  }


  function resetSubheadingIfNeeded(
    semanticBlock
  ) {
    if (
      !currentSubheading
    ) {
      return;
    }


    if (
      !currentSubheading
        .number_info
    ) {
      return;
    }


    const currentText =
      normalizeForDetection(
        semanticBlock.text
      );


    const currentClauseInfo =
      getNumberedClauseInfo(
        currentText
      );


    if (
      !currentClauseInfo
    ) {
      return;
    }


    const stillInsideSubheading =
      isChildClause(
        currentClauseInfo,
        currentSubheading
          .number_info
      );


    if (
      !stillInsideSubheading
    ) {
      currentSubheading =
        null;
    }
  }


  for (
    const semanticBlock
    of semanticBlocks
  ) {

    // --------------------------------------------------------
    // КРУПНЫЙ РАЗДЕЛ
    // --------------------------------------------------------

    if (
      semanticBlock.role ===
      'section_heading'
    ) {
      const title =
        normalizeForDetection(
          semanticBlock.text
        );


      startSection(
        title,
        'section',
        semanticBlock
      );


      semanticBlock
        .section_path =
        [
          currentSection
            .title,
        ];


      continue;
    }


    // Всё до первого раздела -> преамбула.

    if (
      !currentSection
    ) {
      startSection(
        'Преамбула',
        'preamble'
      );
    }


    // --------------------------------------------------------
    // ПОДРАЗДЕЛ
    // --------------------------------------------------------

    if (
      semanticBlock.role ===
      'subsection_heading'
    ) {
      const title =
        normalizeForDetection(
          semanticBlock.text
        );


      currentSubheading = {
        title,

        number_info:
          getNumberedClauseInfo(
            title
          ),
      };


      addToCurrentSection(
        semanticBlock
      );


      semanticBlock
        .section_path =
        [
          currentSection
            .title,

          currentSubheading
            .title,
        ];


      continue;
    }


    // --------------------------------------------------------
    // ОБЫЧНЫЙ ТЕКСТ / ТАБЛИЦА
    // --------------------------------------------------------

    resetSubheadingIfNeeded(
      semanticBlock
    );


    addToCurrentSection(
      semanticBlock
    );
  }


  // ==========================================================
  // ФИНАЛИЗИРУЕМ SECTIONS
  // ==========================================================

  for (
    const section
    of sections
  ) {
    section
      .source_block_ids =
      [
        ...new Set(
          section
            .source_block_ids
        ),
      ];


    section
      .semantic_blocks_count =
      section
        .semantic_block_ids
        .length;
  }


  // ==========================================================
  // 5. КОНТРОЛЬ ПОТЕРЬ
  // ==========================================================

  const sourceUsage =
    new Map();


  for (
    const semanticBlock
    of semanticBlocks
  ) {
    for (
      const blockId
      of semanticBlock
        .source_block_ids
    ) {
      sourceUsage.set(

        blockId,

        (
          sourceUsage.get(
            blockId
          ) ??
          0
        ) +
        1
      );
    }
  }


  const includedSourceIds =
    orderedBlocks.map(
      block =>
        block.block_id
    );


  const missingSourceBlocks =
    includedSourceIds.filter(
      blockId =>
        !sourceUsage.has(
          blockId
        )
    );


  const duplicatedSourceBlocks =
    [
      ...sourceUsage
        .entries(),
    ]
      .filter(
        ([, count]) =>
          count !== 1
      )
      .map(
        ([
          blockId,
          count
        ]) => ({
          block_id:
            blockId,

          count,
        })
      );


  const coverage =
    includedSourceIds.length ===
    0

      ? 1

      : (
          includedSourceIds
            .length -
          missingSourceBlocks
            .length
        ) /
        includedSourceIds
          .length;


  // ==========================================================
  // РЕЗУЛЬТАТ
  // ==========================================================

  return {
    ...input,


    semantic_blocks:
      semanticBlocks,


    sections,


    // --------------------------------------------------------
    // XLSX:
    // постоянный контекст листов.
    //
    // Для PDF/DOCX здесь будет null.
    // --------------------------------------------------------

    spreadsheet_context:
      spreadsheetContext,


    section_building: {

      version:
        '1.4',


      included_source_blocks_count:
        includedSourceIds
          .length,


      semantic_blocks_count:
        semanticBlocks
          .length,


      sections_count:
        sections.length,


      merged_cross_page_continuations_count:
        mergedContinuationsCount,


      // DOCX corrections

      downgraded_parser_subheadings_count:
        downgradedParserSubheadingsCount,


      merged_split_section_headings_count:
        mergedSplitSectionHeadingsCount,


      semantic_corrections_count:
        semanticCorrections
          .length,


      semantic_corrections:
        semanticCorrections,


      // Coverage audit

      missing_source_blocks_count:
        missingSourceBlocks
          .length,


      missing_source_blocks:
        missingSourceBlocks,


      duplicated_source_blocks_count:
        duplicatedSourceBlocks
          .length,


      duplicated_source_blocks:
        duplicatedSourceBlocks,


      coverage,


      data_loss:
        missingSourceBlocks
          .length >
        0,


      warnings,
    },
  };
}


// ============================================================
// ВСЕ ВХОДНЫЕ ITEMS
// ============================================================

return items.map(
  (item, itemIndex) => {

    return {

      json:
        processDocument(
          item.json ??
          {}
        ),

      pairedItem: {
        item:
          itemIndex,
      },
    };
  }
);

// ============================================================
// РАЗВЕРНУТЬ ЧАСТИ ДЛЯ AI v1.2
//
// Вход:
// - один или несколько документов
// - в каждом документе analysis_units[]
// - semantic_blocks[] для построения:
//   1. compact provenance
//   2. ai_segments[]
//
// Выход:
// - отдельный n8n item на каждую analysis_unit
//
// ВАЖНО:
// Не переносим дальше тяжёлые:
// - blocks[]
// - semantic_blocks[]
// - sections[]
// - analysis_sequence[]
//
// Вместо полного semantic_blocks[] создаём:
//
// 1. ai_segments[]
//    Компактная связь:
//    semantic_block_id → текст, который увидит AI.
//
// 2. provenance
//    Компактная связь:
//    semantic_block_id → реальные source blocks / page / bbox.
//
// Таким образом AI сможет точно указывать evidence
// через semantic_block_id, а после AI этот источник
// можно будет проверить детерминированно.
// ============================================================

const items = $input.all();

const output = [];


// ============================================================
// ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
// ============================================================

function uniqueStrings(values) {
  const result = [];
  const seen = new Set();

  for (const value of Array.isArray(values) ? values : []) {
    if (typeof value !== 'string' || value.length === 0) {
      continue;
    }

    if (seen.has(value)) {
      continue;
    }

    seen.add(value);
    result.push(value);
  }

  return result;
}


// ------------------------------------------------------------
// Оставляем bbox компактным и предсказуемым.
//
// Не модифицируем координаты.
// Просто копируем те поля, которые уже пришли
// из Normalizer.
// ------------------------------------------------------------

function compactBbox(bbox) {
  if (
    bbox === null ||
    typeof bbox !== 'object'
  ) {
    return null;
  }

  return {
    l:
      Number.isFinite(bbox.l)
        ? bbox.l
        : null,

    t:
      Number.isFinite(bbox.t)
        ? bbox.t
        : null,

    r:
      Number.isFinite(bbox.r)
        ? bbox.r
        : null,

    b:
      Number.isFinite(bbox.b)
        ? bbox.b
        : null,

    coord_origin:
      bbox.coord_origin ??
      null,
  };
}


// ------------------------------------------------------------
// Компактная информация об одном source block.
//
// Здесь намеренно НЕ переносим:
// - исходный полный block
// - text
// - table.cells
//
// Текст semantic block будет находиться отдельно
// в ai_segments[].
//
// Здесь задача только указать реальный источник.
// ------------------------------------------------------------

function compactSource(source) {
  return {
    block_id:
      source?.block_id ??
      null,

    page_no:
      Number.isFinite(source?.page_no)
        ? source.page_no
        : null,

    bbox:
      compactBbox(source?.bbox),

    label:
      source?.label ??
      null,

    analysis_order:
      Number.isFinite(source?.analysis_order)
        ? source.analysis_order
        : null,
  };
}


// ------------------------------------------------------------
// Создаём compact provenance одного semantic block.
//
// scope:
// - primary  → блок относится к основному тексту unit
// - overlap  → блок передан только как контекст
// ------------------------------------------------------------

function compactSemanticBlock(
  semanticBlock,
  scope
) {
  const sources =
    Array.isArray(semanticBlock?.sources)
      ? semanticBlock.sources
          .map(compactSource)
          .filter(source => source.block_id)
      : [];

  return {
    scope,

    type:
      semanticBlock?.type ??
      null,

    role:
      semanticBlock?.role ??
      null,

    section_id:
      semanticBlock?.section_id ??
      null,

    section_title:
      semanticBlock?.section_title ??
      null,

    section_path:
      Array.isArray(semanticBlock?.section_path)
        ? semanticBlock.section_path
        : [],

    sheet_name:
      semanticBlock?.sheet_name ??
      null,

    page_from:
      Number.isFinite(semanticBlock?.page_from)
        ? semanticBlock.page_from
        : null,

    page_to:
      Number.isFinite(semanticBlock?.page_to)
        ? semanticBlock.page_to
        : null,

    source_block_ids:
      uniqueStrings(
        semanticBlock?.source_block_ids
      ),

    sources,
  };
}


// ------------------------------------------------------------
// Лёгкое представление semantic block для AI.
//
// Здесь сохраняем только минимально нужную связь:
//
// semantic_block_id
//        ↓
// текст, который увидит модель
//
// Благодаря этому AI сможет вернуть:
// evidence.semantic_block_id
//
// и ему не придётся угадывать, к какому semantic block
// относился конкретный абзац.
//
// Полный semantic_blocks[] дальше НЕ переносится.
// ------------------------------------------------------------

function createAiSegment(
  semanticBlock,
  scope,
  optionStateMappingWarnings,
  optionStateStatus,
  optionStateSourceWarnings
) {
  return {
    semantic_block_id:
      semanticBlock?.semantic_block_id ??
      null,

    scope,

    type:
      semanticBlock?.type ??
      null,

    role:
      semanticBlock?.role ??
      null,

    canonical_text:
      typeof semanticBlock?.text === 'string'
        ? semanticBlock.text
        : '',

    text:
      typeof semanticBlock?.ai_text === 'string'
        ? semanticBlock.ai_text
        : (
            typeof semanticBlock?.text === 'string'
              ? semanticBlock.text
              : ''
          ),

    docx_option_states:
      Array.isArray(
        semanticBlock?.docx_option_states
      )
        ? semanticBlock.docx_option_states
        : [],

    option_state_markers:
      Array.isArray(
        semanticBlock?.option_state_markers
      )
        ? semanticBlock.option_state_markers
        : [],

    docx_option_state_mapping_warnings:
      Array.isArray(optionStateMappingWarnings)
        ? optionStateMappingWarnings
        : [],

    docx_option_state_status:
      typeof optionStateStatus === 'string'
        ? optionStateStatus
        : null,

    docx_option_state_source_warnings:
      Array.isArray(optionStateSourceWarnings)
        ? optionStateSourceWarnings
        : [],
  };
}


// ============================================================
// ОСНОВНАЯ ОБРАБОТКА
// ============================================================

for (
  let inputIndex = 0;
  inputIndex < items.length;
  inputIndex++
) {

  const input =
    items[inputIndex]?.json ?? {};


  const analysisUnits =
    Array.isArray(input.analysis_units)
      ? input.analysis_units
      : [];


  const semanticBlocks =
    Array.isArray(input.semantic_blocks)
      ? input.semantic_blocks
      : [];


  // ----------------------------------------------------------
  // Защита от неожиданного пустого документа
  // ----------------------------------------------------------

  if (analysisUnits.length === 0) {
    throw new Error(
      `В документе ${
        input?.document?.file_name ??
        inputIndex
      } отсутствуют analysis_units`
    );
  }


  if (semanticBlocks.length === 0) {
    throw new Error(
      `В документе ${
        input?.document?.file_name ??
        inputIndex
      } отсутствуют semantic_blocks, ` +
      `поэтому невозможно построить provenance и ai_segments`
    );
  }


  // ----------------------------------------------------------
  // Индекс semantic blocks.
  //
  // Позволяет получать блок за O(1), вместо поиска
  // по всему массиву для каждой analysis unit.
  // ----------------------------------------------------------

  const semanticBlockById =
    new Map();


  for (const block of semanticBlocks) {

    const semanticBlockId =
      block?.semantic_block_id;


    if (
      typeof semanticBlockId !== 'string' ||
      semanticBlockId.length === 0
    ) {
      throw new Error(
        `В документе ${
          input?.document?.file_name ??
          inputIndex
        } найден semantic block без semantic_block_id`
      );
    }


    if (
      semanticBlockById.has(
        semanticBlockId
      )
    ) {
      throw new Error(
        `В документе ${
          input?.document?.file_name ??
          inputIndex
        } найден дублирующий semantic_block_id: ` +
        semanticBlockId
      );
    }


    semanticBlockById.set(
      semanticBlockId,
      block
    );
  }


  // ----------------------------------------------------------
  // Разворачиваем каждую analysis unit
  // в отдельный n8n item
  // ----------------------------------------------------------

  for (
    let unitIndex = 0;
    unitIndex < analysisUnits.length;
    unitIndex++
  ) {

    const unit =
      analysisUnits[unitIndex];


    const primaryIds =
      uniqueStrings(
        unit?.primary_semantic_block_ids
      );


    const overlapIds =
      uniqueStrings(
        unit?.overlap_semantic_block_ids
      );


    // --------------------------------------------------------
    // Защита:
    // один semantic block не должен одновременно считаться
    // primary и overlap внутри одной unit.
    // --------------------------------------------------------

    const primarySet =
      new Set(primaryIds);


    const duplicatedScopes =
      overlapIds.filter(
        id => primarySet.has(id)
      );


    if (duplicatedScopes.length > 0) {
      throw new Error(
        `В analysis unit ${
          unit?.analysis_unit_id ??
          unitIndex
        } semantic blocks одновременно находятся ` +
        `в primary и overlap: ` +
        duplicatedScopes.join(', ')
      );
    }


    // ========================================================
    // COMPACT PROVENANCE + AI SEGMENTS
    // ========================================================

    const provenanceIndex = {};

    const aiSegments = [];


    // --------------------------------------------------------
    // PRIMARY
    // --------------------------------------------------------

    for (const semanticBlockId of primaryIds) {

      const semanticBlock =
        semanticBlockById.get(
          semanticBlockId
        );


      if (!semanticBlock) {
        throw new Error(
          `Analysis unit ${
            unit?.analysis_unit_id ??
            unitIndex
          } ссылается на отсутствующий ` +
          `primary semantic block: ` +
          semanticBlockId
        );
      }


      // ------------------------------------------------------
      // Provenance:
      // semantic block → реальный источник
      // ------------------------------------------------------

      provenanceIndex[
        semanticBlockId
      ] =
        compactSemanticBlock(
          semanticBlock,
          'primary'
        );


      // ------------------------------------------------------
      // AI segment:
      // semantic block → его текст
      // ------------------------------------------------------

      aiSegments.push(
        createAiSegment(
          semanticBlock,
          'primary',
          input?.docx_option_state_audit
            ?.semantic_mapping_warnings,
          input?.docx_option_state_status,
          input?.docx_option_state_audit
            ?.warnings
        )
      );
    }


    // --------------------------------------------------------
    // OVERLAP
    // --------------------------------------------------------

    for (const semanticBlockId of overlapIds) {

      const semanticBlock =
        semanticBlockById.get(
          semanticBlockId
        );


      if (!semanticBlock) {
        throw new Error(
          `Analysis unit ${
            unit?.analysis_unit_id ??
            unitIndex
          } ссылается на отсутствующий ` +
          `overlap semantic block: ` +
          semanticBlockId
        );
      }


      // ------------------------------------------------------
      // Provenance
      // ------------------------------------------------------

      provenanceIndex[
        semanticBlockId
      ] =
        compactSemanticBlock(
          semanticBlock,
          'overlap'
        );


      // ------------------------------------------------------
      // AI segment
      // ------------------------------------------------------

      aiSegments.push(
        createAiSegment(
          semanticBlock,
          'overlap',
          input?.docx_option_state_audit
            ?.semantic_mapping_warnings,
          input?.docx_option_state_status,
          input?.docx_option_state_audit
            ?.warnings
        )
      );
    }


    const requestedIds = [
      ...primaryIds,
      ...overlapIds,
    ];


    const resolvedIds =
      Object.keys(
        provenanceIndex
      );


    const aiSegmentIds =
      aiSegments.map(
        segment =>
          segment.semantic_block_id
      );


    // --------------------------------------------------------
    // Контроль provenance:
    //
    // Количество provenance entries должно совпадать
    // с количеством semantic blocks этой unit.
    // --------------------------------------------------------

    if (
      resolvedIds.length !==
      requestedIds.length
    ) {
      throw new Error(
        `Ошибка построения provenance для analysis unit ${
          unit?.analysis_unit_id ??
          unitIndex
        }: ожидалось ${
          requestedIds.length
        } semantic blocks, получено ${
          resolvedIds.length
        }`
      );
    }


    // --------------------------------------------------------
    // Контроль ai_segments:
    //
    // Для каждого semantic block этой unit должен быть
    // ровно один AI segment.
    // --------------------------------------------------------

    if (
      aiSegments.length !==
      requestedIds.length
    ) {
      throw new Error(
        `Ошибка построения ai_segments для analysis unit ${
          unit?.analysis_unit_id ??
          unitIndex
        }: ожидалось ${
          requestedIds.length
        } сегментов, получено ${
          aiSegments.length
        }`
      );
    }


    // --------------------------------------------------------
    // Контроль соответствия ID.
    //
    // Порядок ai_segments должен совпадать с:
    // primaryIds → overlapIds.
    // --------------------------------------------------------

    for (
      let idIndex = 0;
      idIndex < requestedIds.length;
      idIndex++
    ) {

      if (
        requestedIds[idIndex] !==
        aiSegmentIds[idIndex]
      ) {
        throw new Error(
          `Нарушен порядок ai_segments в analysis unit ${
            unit?.analysis_unit_id ??
            unitIndex
          }: ожидался ${
            requestedIds[idIndex]
          }, получен ${
            aiSegmentIds[idIndex]
          }`
        );
      }
    }


    // ========================================================
    // СОЗДАЁМ OUTPUT ITEM
    // ========================================================

    output.push({
      json: {

        analysis_run_id:
          input?.analysis_run_id ?? 
          null,

        // ====================================================
        // ИДЕНТИФИКАЦИЯ ТЕНДЕРА
        // ====================================================

        tender: {
          source:
            input?.tender_meta?.source ??
            null,

          tender_id:
            input?.tender_meta?.tender_id ??
            null,

          tender_number:
            input?.tender_meta?.tender_number ??
            null,

          tender_external_id:
            input?.tender_meta?.tender_external_id ??
            null,

          title:
            input?.tender_meta?.title ??
            null,

          max_price:
            input?.tender_meta?.max_price ??
            null,

          currency:
            input?.tender_meta?.currency ??
            null,

          submission_close_at:
            input?.tender_meta?.submission_close_at ??
            null,

          primary_customer:
            input?.tender_meta?.primary_customer ??
            null,

          platform:
            input?.tender_meta?.platform ??
            null,
        },


        // ====================================================
        // ИДЕНТИФИКАЦИЯ ДОКУМЕНТА
        // ====================================================

        document: {

          document_id:
            input?.document?.document_id ??
            null,

          document_index:
            input?.document?.document_index ??
            null,

          file_name:
            input?.document?.file_name ??
            null,

          file_extension:
            input?.document?.file_extension ??
            null,

          display_name:
            input?.document?.display_name ??
            null,

          parser_provider:
            input?.parser?.provider ??
            null,

          parser_schema:
            input?.parser?.schema ??
            null,
        },


        // ====================================================
        // СЛУЖЕБНАЯ ИНФОРМАЦИЯ О РАЗБИЕНИИ
        // ====================================================

        analysis_batch: {
          unit_index:
            unitIndex + 1,

          units_total:
            analysisUnits.length,

          source_semantic_blocks_count:
            input?.analysis_unit_building
              ?.source_semantic_blocks_count ??
            null,
        },


        // ====================================================
        // КОНКРЕТНАЯ ЧАСТЬ
        // ====================================================

        analysis_unit:
          unit,


        // ====================================================
        // AI SEGMENTS
        //
        // Точная связь:
        //
        // semantic_block_id
        //        ↓
        // текст semantic block
        //
        // Следующая нода сможет сформировать prompt вида:
        //
        // [BLOCK sb_0043]
        // Гарантийный срок...
        //
        // И модель сможет вернуть:
        //
        // evidence:
        // {
        //   semantic_block_id: "sb_0043"
        // }
        // ====================================================

        ai_segments:
          aiSegments,


        // ====================================================
        // COMPACT PROVENANCE
        //
        // Ключ объекта = semantic_block_id.
        //
        // После AI можно будет получить настоящий источник:
        //
        // semantic_block_id
        //        ↓
        // source_block_id
        //        ↓
        // page_no
        //        ↓
        // bbox
        //
        // Для DOCX page/bbox могут быть null —
        // это нормально, если parser их не предоставил.
        // ====================================================

        provenance: {
          version:
            '1.0',

          primary_semantic_blocks_count:
            primaryIds.length,

          overlap_semantic_blocks_count:
            overlapIds.length,

          total_semantic_blocks_count:
            resolvedIds.length,

          index:
            provenanceIndex,
        },
      },


      // ------------------------------------------------------
      // Связываем каждый новый item
      // с исходным item документа.
      // ------------------------------------------------------

      pairedItem: {
        item:
          inputIndex,
      },
    });
  }
}


// ============================================================
// КОНТРОЛЬ
// ============================================================

if (output.length === 0) {
  throw new Error(
    'Не было создано ни одной части для AI'
  );
}


return output;

