const items =
  $input.all();

if (
  items.length === 0
) {
  throw new Error(
    '[Подготовить запрос для AI] Нет входных items.'
  );
}


return items.map(
  (
    item,
    itemIndex
  ) => {
    const input =
      item?.json;

    if (
      !isObject(input)
    ) {
      fail(
        itemIndex,
        'Input JSON отсутствует или имеет неверный формат.'
      );
    }


    // --------------------------------------------------------
    // analysis_unit
    // --------------------------------------------------------

    const unit =
      input.analysis_unit;

    if (
      !isObject(unit)
    ) {
      fail(
        itemIndex,
        'Отсутствует analysis_unit.'
      );
    }


    const analysisUnitId =
      unit.analysis_unit_id;

    if (
      typeof analysisUnitId !== 'string' ||
      analysisUnitId.length === 0
    ) {
      fail(
        itemIndex,
        'analysis_unit.analysis_unit_id отсутствует.'
      );
    }


    if (
      !Array.isArray(
        unit.primary_semantic_block_ids
      )
    ) {
      fail(
        itemIndex,
        `${analysisUnitId}: отсутствует primary_semantic_block_ids.`
      );
    }


    if (
      !Array.isArray(
        unit.overlap_semantic_block_ids
      )
    ) {
      fail(
        itemIndex,
        `${analysisUnitId}: отсутствует overlap_semantic_block_ids.`
      );
    }


    const primaryIds =
      uniqueStrings(
        unit.primary_semantic_block_ids
      );

    const overlapIds =
      uniqueStrings(
        unit.overlap_semantic_block_ids
      );


    if (
      primaryIds.length === 0
    ) {
      fail(
        itemIndex,
        `${analysisUnitId}: нет ни одного primary semantic block.`
      );
    }


    if (
      primaryIds.length !==
      unit.primary_semantic_block_ids.length
    ) {
      fail(
        itemIndex,
        `${analysisUnitId}: primary_semantic_block_ids содержит пустые или дублирующиеся ID.`
      );
    }


    if (
      overlapIds.length !==
      unit.overlap_semantic_block_ids.length
    ) {
      fail(
        itemIndex,
        `${analysisUnitId}: overlap_semantic_block_ids содержит пустые или дублирующиеся ID.`
      );
    }


    const primarySet =
      new Set(primaryIds);

    for (
      const overlapId
      of overlapIds
    ) {
      if (
        primarySet.has(
          overlapId
        )
      ) {
        fail(
          itemIndex,
          `${analysisUnitId}: ${overlapId} одновременно primary и overlap.`
        );
      }
    }


    const expectedIds = [
      ...primaryIds,
      ...overlapIds,
    ];


    // --------------------------------------------------------
    // ai_segments
    // --------------------------------------------------------

    const aiSegments =
      input.ai_segments;

    if (
      !Array.isArray(
        aiSegments
      ) ||
      aiSegments.length === 0
    ) {
      fail(
        itemIndex,
        `${analysisUnitId}: ai_segments отсутствует или пуст.`
      );
    }


    const segmentIds =
      aiSegments.map(
        segment =>
          segment?.semantic_block_id
      );


    if (
      !arraysEqual(
        segmentIds,
        expectedIds
      )
    ) {
      fail(
        itemIndex,
        `${analysisUnitId}: порядок или состав ai_segments не совпадает с primary + overlap semantic IDs.`
      );
    }


    const uniqueSegmentIds =
      uniqueStrings(
        segmentIds
      );

    if (
      uniqueSegmentIds.length !==
      segmentIds.length
    ) {
      fail(
        itemIndex,
        `${analysisUnitId}: ai_segments содержит повторяющиеся semantic_block_id.`
      );
    }


    // --------------------------------------------------------
    // provenance
    // --------------------------------------------------------

    const provenance =
      input.provenance;

    if (
      !isObject(
        provenance
      ) ||
      !isObject(
        provenance.index
      )
    ) {
      fail(
        itemIndex,
        `${analysisUnitId}: provenance.index отсутствует.`
      );
    }


    const provenanceIndex =
      provenance.index;

    const provenanceIds =
      Object.keys(
        provenanceIndex
      );


    if (
      !sameStringSet(
        provenanceIds,
        expectedIds
      )
    ) {
      fail(
        itemIndex,
        `${analysisUnitId}: provenance.index не совпадает с semantic blocks текущей unit.`
      );
    }


    // --------------------------------------------------------
    // Валидация каждого semantic segment
    // --------------------------------------------------------

    for (
      const segment
      of aiSegments
    ) {
      const id =
        segment.semantic_block_id;

      if (
        segment.scope !== 'primary' &&
        segment.scope !== 'overlap'
      ) {
        fail(
          itemIndex,
          `${analysisUnitId}: ${id} имеет недопустимый scope "${segment.scope}".`
        );
      }


      if (
        typeof segment.text !== 'string' ||
        segment.text.trim().length === 0
      ) {
        fail(
          itemIndex,
          `${analysisUnitId}: ${id} содержит пустой text.`
        );
      }


      const provenanceEntry =
        provenanceIndex[id];

      if (
        !isObject(
          provenanceEntry
        )
      ) {
        fail(
          itemIndex,
          `${analysisUnitId}: отсутствует provenance для ${id}.`
        );
      }


      if (
        provenanceEntry.scope !==
        segment.scope
      ) {
        fail(
          itemIndex,
          `${analysisUnitId}: scope ${id} не совпадает между ai_segments и provenance.`
        );
      }
    }


    // --------------------------------------------------------
    // Дополнительная проверка счетчиков provenance
    // --------------------------------------------------------

    if (
      provenance.primary_semantic_blocks_count !==
      primaryIds.length
    ) {
      fail(
        itemIndex,
        `${analysisUnitId}: неверный primary_semantic_blocks_count в provenance.`
      );
    }


    if (
      provenance.overlap_semantic_blocks_count !==
      overlapIds.length
    ) {
      fail(
        itemIndex,
        `${analysisUnitId}: неверный overlap_semantic_blocks_count в provenance.`
      );
    }


    if (
      provenance.total_semantic_blocks_count !==
      expectedIds.length
    ) {
      fail(
        itemIndex,
        `${analysisUnitId}: неверный total_semantic_blocks_count в provenance.`
      );
    }


    // --------------------------------------------------------
    // USER PROMPT
    // --------------------------------------------------------

    const contextLines = [
      `analysis_unit_id: ${analysisUnitId}`,
    ];


    if (
      input.document?.file_name
    ) {
      contextLines.push(
        `Файл документа: ${input.document.file_name}`
      );
    }


    if (
      unit.section_title
    ) {
      contextLines.push(
        `Раздел: ${unit.section_title}`
      );
    }


    if (
      unit.part_index !== undefined &&
      unit.parts_total !== undefined
    ) {
      contextLines.push(
        `Часть раздела: ${unit.part_index} из ${unit.parts_total}`
      );
    }


    if (
      unit.context?.sheet_name
    ) {
      contextLines.push(
        `Excel-лист: ${unit.context.sheet_name}`
      );
    }


    if (
      unit.context?.sheet_title
    ) {
      contextLines.push(
        `Название Excel-листа: ${unit.context.sheet_title}`
      );
    }


    const renderedSegments =
      aiSegments
        .map(
          renderAiSegment
        )
        .join('\n\n');


    const userPrompt = `
Проанализируй только приведённую ниже часть тендерного документа.

Найди все факты из каталога tender_fields_v1, которые явно подтверждаются содержимым SEMANTIC_BLOCK.

Метаданные ниже предоставлены только для навигации и понимания контекста.
Не используй их как evidence.


КОНТЕКСТ

${contextLines.join('\n')}


SEMANTIC BLOCKS

${renderedSegments}


Верни результат строго по схеме ${CONFIG.schemaVersion}.

Если в этой analysis unit нет ни одного целевого факта, верни пустой массив facts.
`.trim();


    // --------------------------------------------------------
    // Оценка размера будущего AI-вызова
    // --------------------------------------------------------

    const systemCharacters =
      SYSTEM_PROMPT.length;

    const userCharacters =
      userPrompt.length;

    const totalCharacters =
      systemCharacters +
      userCharacters;

    const estimatedInputTokens =
      Math.ceil(
        totalCharacters /
        CONFIG.approxCharsPerToken
      );


    // --------------------------------------------------------
    // Минимальная metadata analysis unit для следующих этапов
    // --------------------------------------------------------

    const analysisUnitMeta = {
      analysis_unit_id:
        analysisUnitId,

      section_id:
        unit.section_id ??
        null,

      section_title:
        unit.section_title ??
        null,

      section_kind:
        unit.section_kind ??
        null,

      part_index:
        unit.part_index ??
        null,

      parts_total:
        unit.parts_total ??
        null,

      context:
        unit.context ??
        {},

      source_pages:
        unit.source_pages ??
        [],

      flags:
        unit.flags ??
        {},

      primary_semantic_block_ids:
        primaryIds,

      overlap_semantic_block_ids:
        overlapIds,
    };


    // --------------------------------------------------------
    // OUTPUT
    // --------------------------------------------------------

    return {
      json: {
        // Эти данные сохраняем рядом,
        // но НЕ отправляем модели целиком.
        tender:
          input.tender ??
          null,

        document:
          input.document ??
          null,

        analysis_batch:
          input.analysis_batch ??
          null,

        analysis_unit_meta:
          analysisUnitMeta,

        // Нужны после AI для проверки evidence.
        ai_segments:
          aiSegments,

        // Нужен после AI для восстановления
        // настоящего source/page/bbox.
        provenance,

        ai_request: {
          prompt_version:
            CONFIG.promptVersion,

          schema_version:
            CONFIG.schemaVersion,

          field_catalog_version:
            CONFIG.fieldCatalogVersion,

          system_prompt:
            SYSTEM_PROMPT,

          user_prompt:
            userPrompt,

          response_schema:
            RESPONSE_SCHEMA,

          field_catalog:
            FIELD_CATALOG,

          evidence_resource_contract: {
            max_evidence_per_fact:
              CONFIG.maxEvidencePerFact,
            max_quote_length:
              CONFIG.maxQuoteLength,
            max_total_quote_chars_per_fact:
              CONFIG.maxTotalQuoteCharsPerFact,
            exact_duplicates_allowed:
              false,
            primary_grounded_evidence_required:
              true,
          },

          stats: {
            system_characters:
              systemCharacters,

            user_characters:
              userCharacters,

            total_characters:
              totalCharacters,

            estimated_input_tokens:
              estimatedInputTokens,

            semantic_blocks_count:
              aiSegments.length,

            primary_blocks_count:
              primaryIds.length,

            overlap_blocks_count:
              overlapIds.length,
          },
        },
      },

      // Сохраняем связь с конкретным входным item.
      pairedItem: {
        item: itemIndex,
      },
    };
  }
);

parameters.jsonBody:
={{
{
  model: 'z-ai/glm-5.3-flash@provider=cloudflare&reasoning_effort=low',

  messages: [
    {
      role: 'system',
      content: $json.ai_request.system_prompt
    },
    {
      role: 'user',
      content: $json.ai_request.user_prompt
    }
  ],


  response_format: {
    type: 'json_object'
  },

  max_tokens: 16384,

  stream: false
}
}}

={{
{
  model: 'google/gemini-3.7-flash@provider=google-ai-studio/flex&reasoning_effort=low',

  messages: [
    {
      role: 'system',
      content: `Ты — независимый AI Validator уже извлечённых фактов из тендерной документации.

Твоя задача — проверить каждый переданный fact по его собственному evidence и вернуть один verdict. Не извлекай новые facts, не меняй fact_index, field_key или value_text, не объединяй facts, не нормализуй значения и не формируй итоговый отчёт. Не используй внешние знания, типичные правила закупок или confidence Extractor как доказательство.

УНИВЕРСАЛЬНАЯ SEMANTIC ПРОВЕРКА

Для каждого fact независимо установи:

1. CURRENT SCOPE
К какому объекту относится утверждение: текущая закупка; договор, заключаемый по текущей закупке; другой связанный или упомянутый договор; приложение, форма или шаблон; вспомогательное соглашение; внутренний процесс организации; справочная или нормативная информация.
Свойства связанного объекта нельзя переносить на текущую закупку или текущий договор.

2. ACTOR
Кто является обязанной или описываемой стороной: участник закупки; заказчик; поставщик после заключения договора; гарант; банк; производитель; грузополучатель; иное третье лицо.
Обязанность одного actor нельзя классифицировать как обязанность другого.

3. PROCESS STAGE
На какой стадии действует требование: подготовка и подача заявки; рассмотрение или оценка; заключение договора; исполнение договора; поставка и приёмка; оплата; гарантийный период; внутренний аудит или квалификация; вспомогательный процесс.
Информация одной стадии не должна попадать в поле другой стадии без прямого подтверждения источником.

4. SEMANTIC OBJECT
Что описывает evidence: основной предмет поставки, работ или услуг; документ; срок; место; способ; денежное обязательство; обеспечение; разрешение или сертификат; банковские реквизиты; критерий оценки; организационный процесс; вспомогательное условие.
Совпадение отдельных слов не доказывает совпадение semantic object.

5. ASSERTION TYPE
Что делает источник: прямо устанавливает обязательное условие; сообщает фактическое значение; допускает возможность; приводит условный случай; содержит пример; содержит незаполненную форму; ссылается на другой документ; описывает общий порядок; содержит только заголовок.
Только прямое утверждение или обязанность может быть confirmed, если профиль поля требует конкретного условия.

6. FACT-LOCAL EVIDENCE COVERAGE
Каждая существенная часть value_text должна подтверждаться evidence[] именно этого fact.
evidence_context разрешено использовать только для определения контекста, разрешения ссылок и местоимений и понимания actor, scope и process stage.
evidence_context нельзя использовать для добавления отсутствующей существенной части value_text, замены отсутствующего fact evidence, объединения разных требований или подтверждения fact evidence другого candidate fact.

UNIVERSAL DECISION RULE

confirmed разрешен только если одновременно:
- текущий scope однозначно установлен;
- actor, process stage и semantic object соответствуют field_key;
- источник содержит требуемый assertion type;
- все существенные части value_text подтверждены fact evidence;
- нет существенных пропусков, условий, исключений или placeholders;
- выполнены positive confirmation criteria переданного профиля поля.

rejected используй, если:
- evidence прямо относится к другому scope, actor, stage или semantic object;
- field_key классифицирован неверно;
- value_text содержит существенное утверждение, противоречащее evidence;
- характеристика связанного объекта перенесена на текущий объект;
- информационный, справочный или вспомогательный текст выдан за условие закупки;
- выполнено условие rejected переданного профиля.

requires_review используй, если:
- факт потенциально релевантен, но scope, actor, stage или обязательность нельзя установить однозначно;
- evidence подтверждает только часть существенного value_text;
- источник является шаблоном с незаполненными существенными параметрами;
- для безопасного решения требуется контекст, отсутствующий в fact evidence;
- выполнено условие requires_review переданного профиля.

Не используй requires_review для очевидно неправильной классификации. Не используй rejected только из-за незначительного форматирования, если бизнес-смысл и значение однозначно подтверждены. Отсутствие информации не доказывает отрицательное значение.

ПРОФИЛИ ПОЛЕЙ ТЕКУЩЕЙ ANALYSIS UNIT

Ниже переданы профили ровно тех уникальных field_key, которые присутствуют в verified_facts текущей unit. Применяй профиль с тем же field_key; не придумывай правила отсутствующих полей.

${$json.validator_prompt_context.field_profiles_text}

REASON CODES

Для confirmed:
reason_code = null
reason_note = null

Для requires_review или rejected используй один reason_code:
wrong_field_classification
value_not_supported
overinterpretation
missing_qualification
insufficient_evidence
conflicting_evidence
source_quality_issue
template_or_placeholder
other

КОНТРАКТ ОТВЕТА

Верни только один JSON-объект без Markdown:
{
  "schema_version": "ai_validator_v1",
  "analysis_unit_id": "тот же analysis_unit_id",
  "validations": [
    {
      "fact_index": 0,
      "field_key": "тот же field_key",
      "verdict": "confirmed | requires_review | rejected",
      "confidence": 0.0,
      "reason_code": null,
      "reason_note": null
    }
  ]
}

Верни ровно один validation для каждого переданного fact. Не пропускай и не добавляй facts. fact_index и field_key должны совпадать с исходным fact. Обработай каждый fact независимо.`
    },

    {
      role: 'user',
      content: `Проверь следующие результаты AI Extractor.

analysis_unit_id:
${$json.analysis_unit_meta.analysis_unit_id}

КАНДИДАТЫ FACTS:

${JSON.stringify(
  $json.verified_facts.map(fact => ({
    fact_index: fact.fact_index,
    field_key: fact.field_key,
    value_text: fact.value_text,
    extractor_status: fact.status,
    extractor_confidence: fact.confidence,
    extractor_review_reason_code: fact.review_reason_code,
    extractor_review_note: fact.review_note,
    evidence: fact.evidence.map(evidence => ({
      semantic_block_id: evidence.semantic_block_id,
      quote: evidence.quote,
      scope: evidence.scope
    }))
  })),
  null,
  2
)}

ПОЛНЫЙ ТЕКСТ ИСПОЛЬЗОВАННЫХ SEMANTIC BLOCKS:

${JSON.stringify(
  Object.values($json.evidence_context).map(block => ({
    semantic_block_id: block.semantic_block_id,
    scope: block.scope,
    type: block.type,
    role: block.role,
    text: block.text
  })),
  null,
  2
)}

Проверь каждый fact независимо и верни результат строго по ai_validator_v1.`
    }
  ],

  response_format: {
    type: 'json_object'
  },

  max_tokens: 8192,

  stream: false
}
}}

parameters.jsCode:
const CONFIG = {
  validatorVersion: 'evidence_validator_v2',
  expectedSchemaVersion: 'ai_extractor_v1',
  expectedFieldCatalogVersion: 'tender_fields_v1',
  maxFactsPerUnit: 100,
  maxEvidencePerFact: 25,
  maxQuoteLength: 1500,
  maxTotalQuoteCharsPerFact: 5000,
  maxValueTextLength: 3000,
  maxReviewNoteLength: 500,
};

const FIELD_KEYS = new Set([
  'procurement_subject', 'nm_price_with_vat', 'platform', 'procedure_type',
  'application_deadline', 'application_review_date', 'results_date', 'customer',
  'customer_contacts', 'participation_cost', 'participation_guarantee',
  'evaluation_criteria', 'delivery_term', 'payment_terms',
  'special_account_or_treasury', 'bank_support', 'government_contract',
  'rebidding', 'national_regime', 'advance_contract_guarantee',
  'warranty_obligations_guarantee', 'licenses_certificates',
  'required_official_certificates', 'similar_supply_experience',
  'analog_allowed', 'analog_definition', 'application_documents',
]);
const REVIEW_REASON_CODES = new Set([
  'ambiguous_wording', 'conflicting_evidence', 'incomplete_value',
  'unclear_reference', 'source_quality_issue', 'other',
]);
const ROOT_KEYS = new Set([
  'schema_version', 'field_catalog_version', 'analysis_unit_id', 'facts',
]);
const FACT_KEYS = new Set([
  'field_key', 'value_text', 'status', 'confidence', 'evidence',
  'review_reason_code', 'review_note',
]);
const EVIDENCE_KEYS = new Set(['semantic_block_id', 'quote']);

function hard(message) {
  throw new Error('[Evidence validator] ' + message);
}
function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}
const TABLE_COORDINATE_TOKEN_AT_LINE_START = /^[\t ]*\[(?:C[1-9]\d*(?:-C[1-9]\d*)?|R[1-9]\d*(?:-R[1-9]\d*)?,C[1-9]\d*(?:-C[1-9]\d*)?)\][\t ]*/gm;
function normalizeEvidenceWhitespace(value, segmentType = null) {
  const source = String(value ?? '');
  const canonical = segmentType === 'table'
    ? source.replace(TABLE_COORDINATE_TOKEN_AT_LINE_START, '')
    : source;
  return canonical.replace(/\s+/g, ' ').trim();
}
function isExactGroundedEvidence(segment, quote) {
  if (!segment) return false;
  const normalizedQuote = normalizeEvidenceWhitespace(quote, segment.type);
  if (normalizedQuote.length === 0) return false;
  const normalizedSegment = normalizeEvidenceWhitespace(segment.canonical_text ?? segment.text, segment.type);
  return normalizedSegment.includes(normalizedQuote);
}
function assertExactKeys(value, allowed, path) {
  if (!isObject(value)) hard(path + ': ожидался object.');
  for (const key of Object.keys(value)) {
    if (!allowed.has(key)) hard(path + ': недопустимое поле ' + key + '.');
  }
}
function assertString(value, path, minLength = 1, maxLength = Infinity) {
  if (typeof value !== 'string') hard(path + ': ожидалась string.');
  if (value.length < minLength || value.length > maxLength) {
    hard(path + ': недопустимая длина ' + value.length + '.');
  }
}
function parseProviderResponse(apiResponse, expectedRootSchema) {
  if (!isObject(apiResponse)) hard('Некорректный HTTP response.');
  if (!Array.isArray(apiResponse.choices) || apiResponse.choices.length === 0) {
    hard('Provider не вернул choices.');
  }
  const choice = apiResponse.choices[0];
  if (!isObject(choice) || choice.finish_reason !== 'stop' || !isObject(choice.message)) {
    hard('Provider response не завершён корректно.');
  }
  assertString(choice.message.content, 'choices[0].message.content');
  let parsed;
  try {
    parsed = JSON.parse(choice.message.content.trim());
  } catch (error) {
    hard('Ответ не является валидным JSON: ' + error.message);
  }
  if (!isObject(parsed)) hard('Корневой JSON должен быть object.');
  if (expectedRootSchema === 'extractor') assertExactKeys(parsed, ROOT_KEYS, 'AIExtractorV1');
  return { choice, parsed };
}
function buildSourceIndexes(source) {
  const unitId = source?.analysis_unit_meta?.analysis_unit_id;
  assertString(unitId, 'analysis_unit_meta.analysis_unit_id');
  if (!Array.isArray(source.ai_segments) || source.ai_segments.length === 0) {
    hard(unitId + ': ai_segments отсутствует.');
  }
  if (!isObject(source.provenance?.index)) hard(unitId + ': provenance.index отсутствует.');
  const segmentMap = new Map();
  for (const segment of source.ai_segments) {
    if (!isObject(segment)) hard(unitId + ': invalid ai_segment.');
    assertString(segment.semantic_block_id, unitId + '.semantic_block_id');
    assertString(segment.text, unitId + '.' + segment.semantic_block_id + '.text');
    if (segment.scope !== 'primary' && segment.scope !== 'overlap') {
      hard(unitId + ': invalid scope for ' + segment.semantic_block_id + '.');
    }
    if (segmentMap.has(segment.semantic_block_id)) {
      hard(unitId + ': duplicate semantic_block_id ' + segment.semantic_block_id + '.');
    }
    segmentMap.set(segment.semantic_block_id, segment);
  }
  return { unitId, segmentMap, provenanceIndex: source.provenance.index };
}
function addViolation(violations, code, factIndex, evidenceIndex, details = {}) {
  violations.push({ code, fact_index: factIndex, evidence_index: evidenceIndex, details });
}
function validateFacts(facts, source, validationAttempt = 1) {
  if (!Array.isArray(facts)) hard('facts должен быть array.');
  if (facts.length > CONFIG.maxFactsPerUnit) hard('facts превышает ' + CONFIG.maxFactsPerUnit + '.');
  const { unitId, segmentMap, provenanceIndex } = buildSourceIndexes(source);
  const violations = [];
  const verifiedFacts = [];
  const deterministicallyRejectedFacts = [];
  const resolvedViolations = [];
  const evidenceContext = {};
  const metrics = {
    facts_count: facts.length,
    evidence_count: 0,
    max_evidence_count_per_fact: 0,
    total_quote_chars: 0,
    max_total_quote_chars_per_fact: 0,
    duplicate_evidence_count: 0,
  };

  facts.forEach((fact, factIndex) => {
    const factPath = 'facts[' + factIndex + ']';
    assertExactKeys(fact, FACT_KEYS, factPath);
    for (const required of FACT_KEYS) {
      if (!Object.prototype.hasOwnProperty.call(fact, required)) hard(factPath + ': отсутствует ' + required + '.');
    }
    assertString(fact.field_key, factPath + '.field_key');
    if (!FIELD_KEYS.has(fact.field_key)) hard(factPath + ': недопустимый field_key ' + fact.field_key + '.');
    assertString(fact.value_text, factPath + '.value_text', 1, CONFIG.maxValueTextLength);
    if (fact.status !== 'found' && fact.status !== 'requires_review') hard(factPath + ': invalid status.');
    if (typeof fact.confidence !== 'number' || !Number.isFinite(fact.confidence) || fact.confidence < 0 || fact.confidence > 1) {
      hard(factPath + ': invalid confidence.');
    }
    if (fact.status === 'found' && (fact.review_reason_code !== null || fact.review_note !== null)) {
      hard(factPath + ': review fields должны быть null для found.');
    }
    if (fact.status === 'requires_review') {
      if (!REVIEW_REASON_CODES.has(fact.review_reason_code)) hard(factPath + ': invalid review_reason_code.');
      if (fact.review_note !== null) assertString(fact.review_note, factPath + '.review_note', 0, CONFIG.maxReviewNoteLength);
    }
    if (!Array.isArray(fact.evidence) || fact.evidence.length === 0) {
      hard(factPath + ': evidence отсутствует или пуст.');
    }

    const factViolations = [];
    const totalQuoteChars = fact.evidence.reduce((sum, evidence) => sum + (typeof evidence?.quote === 'string' ? evidence.quote.length : 0), 0);
    metrics.evidence_count += fact.evidence.length;
    metrics.total_quote_chars += totalQuoteChars;
    metrics.max_evidence_count_per_fact = Math.max(metrics.max_evidence_count_per_fact, fact.evidence.length);
    metrics.max_total_quote_chars_per_fact = Math.max(metrics.max_total_quote_chars_per_fact, totalQuoteChars);
    if (fact.evidence.length > CONFIG.maxEvidencePerFact) {
      addViolation(factViolations, 'evidence_limit_exceeded', factIndex, null, {
        actual: fact.evidence.length, maximum: CONFIG.maxEvidencePerFact,
      });
    }
    if (totalQuoteChars > CONFIG.maxTotalQuoteCharsPerFact) {
      addViolation(factViolations, 'evidence_total_quote_chars_exceeded', factIndex, null, {
        actual: totalQuoteChars, maximum: CONFIG.maxTotalQuoteCharsPerFact,
      });
    }

    const seen = new Set();
    const groundedEvidence = [];
    fact.evidence.forEach((evidence, evidenceIndex) => {
      const evidencePath = factPath + '.evidence[' + evidenceIndex + ']';
      assertExactKeys(evidence, EVIDENCE_KEYS, evidencePath);
      for (const required of EVIDENCE_KEYS) {
        if (!Object.prototype.hasOwnProperty.call(evidence, required)) hard(evidencePath + ': отсутствует ' + required + '.');
      }
      assertString(evidence.semantic_block_id, evidencePath + '.semantic_block_id', 1, 120);
      if (!/^sb_[A-Za-z0-9_-]+$/.test(evidence.semantic_block_id)) hard(evidencePath + ': invalid semantic_block_id shape.');
      assertString(evidence.quote, evidencePath + '.quote', 1, CONFIG.maxQuoteLength);
      const pairKey = evidence.semantic_block_id + '\u0000' + evidence.quote;
      if (seen.has(pairKey)) {
        metrics.duplicate_evidence_count += 1;
        addViolation(factViolations, 'duplicate_evidence', factIndex, evidenceIndex, {
          semantic_block_id: evidence.semantic_block_id,
        });
        return;
      }
      seen.add(pairKey);

      const segment = segmentMap.get(evidence.semantic_block_id);
      if (!segment) {
        const candidateIds = [...segmentMap.values()]
          .filter((candidate) => isExactGroundedEvidence(candidate, evidence.quote))
          .map((candidate) => candidate.semantic_block_id);
        addViolation(factViolations, 'unknown_semantic_block_id', factIndex, evidenceIndex, {
          semantic_block_id: evidence.semantic_block_id,
          exact_match_candidate_ids: candidateIds,
        });
        return;
      }
      const provenance = provenanceIndex[evidence.semantic_block_id];
      if (!isObject(provenance)) hard(evidencePath + ': provenance отсутствует.');
      if (provenance.scope !== segment.scope) hard(evidencePath + ': scope mismatch in provenance.');
      if (!isExactGroundedEvidence(segment, evidence.quote)) {
        const candidateIds = [...segmentMap.values()]
          .filter((candidate) => candidate.semantic_block_id !== evidence.semantic_block_id)
          .filter((candidate) => isExactGroundedEvidence(candidate, evidence.quote))
          .map((candidate) => candidate.semantic_block_id);
        addViolation(
          factViolations,
          candidateIds.length > 0 ? 'wrong_semantic_block_id' : 'quote_not_found',
          factIndex,
          evidenceIndex,
          {
            semantic_block_id: evidence.semantic_block_id,
            exact_match_candidate_ids: candidateIds,
          },
        );
        return;
      }
      groundedEvidence.push({
        semantic_block_id: evidence.semantic_block_id,
        quote: evidence.quote,
        scope: segment.scope,
        type: segment.type ?? null,
        role: segment.role ?? null,
        source_block_ids: Array.isArray(provenance.source_block_ids) ? provenance.source_block_ids : [],
        page_from: provenance.page_from ?? null,
        page_to: provenance.page_to ?? null,
        sheet_name: provenance.sheet_name ?? null,
        sources: Array.isArray(provenance.sources) ? provenance.sources : [],
      });
    });

    if (!groundedEvidence.some((evidence) => evidence.scope === 'primary')) {
      const allGroundedOverlap = groundedEvidence.length === fact.evidence.length && groundedEvidence.every((evidence) => evidence.scope === 'overlap');
      addViolation(
        factViolations,
        allGroundedOverlap ? 'overlap_only' : 'missing_primary_evidence',
        factIndex,
        null,
        { grounded_evidence_count: groundedEvidence.length },
      );
    }
    const registerGroundedEvidenceContext = () => {
      for (const evidence of groundedEvidence) {
        const segment = segmentMap.get(evidence.semantic_block_id);
        const provenance = provenanceIndex[evidence.semantic_block_id];
        evidenceContext[evidence.semantic_block_id] = {
          semantic_block_id: evidence.semantic_block_id,
          scope: segment.scope,
          type: segment.type ?? null,
          role: segment.role ?? null,
          text: segment.text,
          canonical_text: segment.canonical_text ?? segment.text,
          docx_option_states: Array.isArray(segment.docx_option_states) ? segment.docx_option_states : [],
          docx_option_state_mapping_warnings: Array.isArray(segment.docx_option_state_mapping_warnings) ? segment.docx_option_state_mapping_warnings : [],
          docx_option_state_status: typeof segment.docx_option_state_status === 'string' ? segment.docx_option_state_status : null,
          docx_option_state_source_warnings: Array.isArray(segment.docx_option_state_source_warnings) ? segment.docx_option_state_source_warnings : [],
          provenance,
        };
      }
    };
    const pureOverlapOnly = (
      factViolations.length === 1 &&
      factViolations[0].code === 'overlap_only'
    );
    if (pureOverlapOnly) {
      registerGroundedEvidenceContext();
      const originalViolationCodes = factViolations.map(({ code }) => code);
      deterministicallyRejectedFacts.push({
        fact_index: factIndex,
        field_key: fact.field_key,
        value_text: fact.value_text,
        status: fact.status,
        confidence: fact.confidence,
        evidence: groundedEvidence,
        review_reason_code: fact.review_reason_code,
        review_note: fact.review_note,
        validator_verdict: 'rejected',
        validator_confidence: 1.0,
        validator_reason_code: 'overlap_only_context_only',
        accepted_for_normalization: false,
        original_violations: factViolations.map((violation) => ({ ...violation })),
        deterministic_rejection: {
          version: 'deterministic_overlap_rejection_v1',
          validation_attempt: validationAttempt,
          reason_code: 'overlap_only_context_only',
          grounding: 'exact',
          evidence_scope: 'overlap_only',
        },
        validator_meta: {
          origin: 'deterministic_evidence_layer',
          ai_validator_called_for_fact: false,
          grounding: 'exact',
          evidence_scope: 'overlap_only',
          analysis_unit_id: unitId,
          fact_index: factIndex,
          version: 'deterministic_overlap_rejection_v1',
          validation_attempt: validationAttempt,
          original_violation_codes: originalViolationCodes,
        },
      });
      resolvedViolations.push(...factViolations);
    } else {
      violations.push(...factViolations);
      if (factViolations.length === 0) {
        registerGroundedEvidenceContext();
        verifiedFacts.push({
          fact_index: factIndex,
          field_key: fact.field_key,
          value_text: fact.value_text,
          status: fact.status,
          confidence: fact.confidence,
          evidence: groundedEvidence,
          review_reason_code: fact.review_reason_code,
          review_note: fact.review_note,
        });
      }
    }
  });

  violations.sort((left, right) =>
    (left.fact_index - right.fact_index) ||
    ((left.evidence_index ?? -1) - (right.evidence_index ?? -1)) ||
    left.code.localeCompare(right.code),
  );
  const violationsByCode = {};
  for (const violation of [...violations, ...resolvedViolations]) {
    violationsByCode[violation.code] = (violationsByCode[violation.code] ?? 0) + 1;
  }
  metrics.violations_by_code = violationsByCode;
  metrics.unresolved_violations_count = violations.length;
  metrics.resolved_violations_count = resolvedViolations.length;
  metrics.deterministically_rejected_facts_count = deterministicallyRejectedFacts.length;
  return {
    unitId,
    violations,
    verifiedFacts,
    deterministicallyRejectedFacts,
    resolvedViolations,
    evidenceContext,
    metrics,
  };
}

const apiResponse = $json;
const source = $('Подготовить запрос для AI').item.json;
if (!isObject(source)) hard('Не удалось восстановить source analysis unit.');
const { choice, parsed } = parseProviderResponse(apiResponse, 'extractor');
if (parsed.schema_version !== CONFIG.expectedSchemaVersion) hard('Неверный schema_version.');
if (parsed.field_catalog_version !== CONFIG.expectedFieldCatalogVersion) hard('Неверный field_catalog_version.');
const expectedUnitId = source.analysis_unit_meta?.analysis_unit_id;
if (parsed.analysis_unit_id !== expectedUnitId) hard('analysis_unit_id не совпадает.');
const validation = validateFacts(parsed.facts, source, 1);
const usage = isObject(apiResponse.usage) ? apiResponse.usage : {};
const extractor = {
  provider: 'deepseek',
  response_id: apiResponse.id ?? null,
  model: apiResponse.model ?? null,
  finish_reason: choice.finish_reason,
  system_fingerprint: apiResponse.system_fingerprint ?? null,
  prompt_version: source.ai_request?.prompt_version ?? null,
  schema_version: parsed.schema_version,
  field_catalog_version: parsed.field_catalog_version,
  repair: { attempted: false, requests_count: 0 },
  evidence_diagnostics: {
    validator_version: CONFIG.validatorVersion,
    attempt: 1,
    validation_passed: validation.violations.length === 0,
    resource_contract: {
      max_evidence_per_fact: CONFIG.maxEvidencePerFact,
      max_quote_length: CONFIG.maxQuoteLength,
      max_total_quote_chars_per_fact: CONFIG.maxTotalQuoteCharsPerFact,
    },
    resource_metrics: validation.metrics,
    violations: validation.violations,
    resolved_violations: validation.resolvedViolations,
    deterministically_rejected_facts_count: validation.deterministicallyRejectedFacts.length,
  },
  usage,
};
const passed = validation.violations.length === 0;
return {
  json: {
    tender: source.tender ?? null,
    document: source.document ?? null,
    analysis_batch: source.analysis_batch ?? null,
    analysis_unit_meta: source.analysis_unit_meta ?? null,
    validation_attempt: 1,
    validation_passed: passed,
    violations: validation.violations,
    verified_facts: validation.verifiedFacts,
    deterministically_rejected_facts: validation.deterministicallyRejectedFacts,
    resolved_violations: validation.resolvedViolations,
    evidence_context: validation.evidenceContext,
    extractor,
    evidence_validation: {
      version: CONFIG.validatorVersion,
      attempt: 1,
      passed,
      facts_count: validation.verifiedFacts.length,
      deterministically_rejected_facts_count: validation.deterministicallyRejectedFacts.length,
      evidence_count: [...validation.verifiedFacts, ...validation.deterministicallyRejectedFacts].reduce((sum, fact) => sum + fact.evidence.length, 0),
      resource_contract: {
        max_evidence_per_fact: CONFIG.maxEvidencePerFact,
        max_quote_length: CONFIG.maxQuoteLength,
        max_total_quote_chars_per_fact: CONFIG.maxTotalQuoteCharsPerFact,
      },
      resource_metrics: validation.metrics,
      violations_count: validation.violations.length,
    },
    repair_context: passed ? null : {
      original_extractor_response: parsed,
      original_api_response_meta: extractor,
      ai_segments: source.ai_segments,
      provenance: source.provenance,
      field_catalog: source.ai_request?.field_catalog ?? [],
      source,
    },
  },
};

// ============================================================
// СОБРАТЬ ФАКТЫ ДОКУМЕНТА
//
// Вход:
//   все items после "Проверить ответ AI Validator"
//
// Дополнительный источник:
//   "Сохранить analysis unit"
//
// Результат:
//   1 n8n item = 1 полностью проанализированный документ
//
// ВАЖНО:
// - ничего не объединяем по field_key;
// - не удаляем дубли;
// - не выбираем "лучший" факт;
// - не создаём global not_found;
// - каждый fact сохраняет свой analysis_unit_id.
// ============================================================


// ------------------------------------------------------------
// 1. INPUT
// ------------------------------------------------------------

const validatedItems = $input.all();

const savedUnitItems =
  $('Сохранить analysis unit').all();


if (validatedItems.length === 0) {
  throw new Error(
    '[Собрать факты документа] Нет результатов AI Validator.'
  );
}


if (savedUnitItems.length === 0) {
  throw new Error(
    '[Собрать факты документа] Нет сохранённых analysis units.'
  );
}


// ------------------------------------------------------------
// 2. ИНДЕКС СОХРАНЁННЫХ UNITS
// ------------------------------------------------------------

const savedByUnitId = new Map();


for (const item of savedUnitItems) {
  const data = item?.json ?? {};

  const unitId =
    data.analysis_unit?.analysis_unit_id ??
    data.analysis_unit_id ??
    null;

  if (!unitId) {
    throw new Error(
      '[Собрать факты документа] ' +
      'У сохранённой analysis unit отсутствует analysis_unit_id.'
    );
  }

  if (savedByUnitId.has(unitId)) {
    throw new Error(
      `[Собрать факты документа] Дублирующийся analysis_unit_id: ${unitId}`
    );
  }

  savedByUnitId.set(
    unitId,
    data
  );
}


// ------------------------------------------------------------
// 3. ПРОВЕРЯЕМ, ЧТО ВСЕ UNITS ОДНОГО DOCUMENT / RUN
// ------------------------------------------------------------

const firstSaved =
  savedUnitItems[0].json;


const analysisRunId =
  firstSaved.analysis_run_id ??
  null;


const documentId =
  firstSaved.document?.document_id ??
  null;


if (!analysisRunId) {
  throw new Error(
    '[Собрать факты документа] analysis_run_id отсутствует.'
  );
}


if (!documentId) {
  throw new Error(
    '[Собрать факты документа] document_id отсутствует.'
  );
}


for (const item of savedUnitItems) {
  const data = item.json;

  if (
    data.analysis_run_id !==
    analysisRunId
  ) {
    throw new Error(
      '[Собрать факты документа] ' +
      'В execution обнаружены units разных analysis_run_id.'
    );
  }

  if (
    data.document?.document_id !==
    documentId
  ) {
    throw new Error(
      '[Собрать факты документа] ' +
      'В execution обнаружены units разных документов.'
    );
  }
}


// ------------------------------------------------------------
// 4. ПРОВЕРКА КОЛИЧЕСТВА UNITS
// ------------------------------------------------------------

const expectedUnits =
  Number(
    firstSaved.analysis_batch?.units_total ??
    savedUnitItems.length
  );


if (
  savedUnitItems.length !==
  expectedUnits
) {
  throw new Error(
    '[Собрать факты документа] ' +
    `В Postgres-сохранении ожидалось ${expectedUnits} units, ` +
    `получено ${savedUnitItems.length}.`
  );
}


if (
  validatedItems.length !==
  expectedUnits
) {
  throw new Error(
    '[Собрать факты документа] ' +
    `После AI ожидалось ${expectedUnits} units, ` +
    `получено ${validatedItems.length}.`
  );
}


// ------------------------------------------------------------
// 5. СОБИРАЕМ ВСЕ FACTS
// ------------------------------------------------------------

const facts = [];

const analysisUnitIds = [];

let confirmedCount = 0;
let requiresReviewCount = 0;
let rejectedCount = 0;


for (
  let itemIndex = 0;
  itemIndex < validatedItems.length;
  itemIndex++
) {
  const result =
    validatedItems[itemIndex]?.json ??
    {};


  const analysisUnitId =
    result.analysis_unit_meta?.analysis_unit_id ??
    null;


  if (!analysisUnitId) {
    throw new Error(
      `[Собрать факты документа] ` +
      `Item ${itemIndex + 1}: analysis_unit_id отсутствует.`
    );
  }

  if (analysisUnitIds.includes(analysisUnitId)) {
    throw new Error(
      `[Собрать факты документа] Дублирующийся validated analysis_unit_id: ${analysisUnitId}`
    );
  }


  const savedUnit =
    savedByUnitId.get(
      analysisUnitId
    );


  if (!savedUnit) {
    throw new Error(
      `[Собрать факты документа] ` +
      `Не найдена сохранённая unit ${analysisUnitId}.`
    );
  }


  if (
    result.document?.document_id !==
    documentId
  ) {
    throw new Error(
      `[Собрать факты документа] ` +
      `${analysisUnitId}: document_id не совпадает.`
    );
  }


  analysisUnitIds.push(
    analysisUnitId
  );


  const unitFacts =
    Array.isArray(
      result.validated_facts
    )
      ? result.validated_facts
      : [];


  for (const fact of unitFacts) {
    const verdict =
      fact.ai_validation?.verdict ??
      null;


    if (verdict === 'confirmed') {
      confirmedCount++;
    }

    if (verdict === 'requires_review') {
      requiresReviewCount++;
    }

    if (verdict === 'rejected') {
      rejectedCount++;
    }


    facts.push({

      // ----------------------------------------
      // Где именно был найден fact
      // ----------------------------------------

      analysis_unit_id:
        analysisUnitId,

      unit_db_id:
        savedUnit.unit_db_id ??
        null,


      // ----------------------------------------
      // Индекс внутри конкретной unit
      // ----------------------------------------

      fact_index:
        fact.fact_index,


      // ----------------------------------------
      // Каталог
      // ----------------------------------------

      field_catalog_version:
        result.extractor?.field_catalog_version ??
        'tender_fields_v1',


      // ----------------------------------------
      // Сам факт
      // ----------------------------------------

      field_key:
        fact.field_key,

      value_text:
        fact.value_text,


      // ----------------------------------------
      // Первый AI
      // ----------------------------------------

      extractor:
        fact.extractor ?? {},


      // ----------------------------------------
      // Второй AI
      // ----------------------------------------

      ai_validation:
        fact.ai_validation ?? {},


      processing_status:
        fact.processing_status ??
        null,

      accepted_for_normalization:
        fact.accepted_for_normalization ??
        false,


      // ----------------------------------------
      // Evidence
      // ----------------------------------------

      evidence:
        Array.isArray(fact.evidence)
          ? fact.evidence
          : [],


      // ----------------------------------------
      // Метаданные конкретных AI-вызовов
      // пригодятся для аудита
      // ----------------------------------------

      extractor_meta:
        result.extractor ?? {},

      validator_meta:
        fact.option_state_applicability
          ? {
              ...(
                fact.validator_meta ??
                result.ai_validator ??
                {}
              ),
              option_state: {
                contract_version:
                  'docx_option_state_fact_audit_v1',
                applicability:
                  fact.option_state_applicability,
                evidence:
                  Array.isArray(fact.option_state_evidence)
                    ? fact.option_state_evidence
                    : [],
                warnings:
                  Array.isArray(fact.option_state_audit_warnings)
                    ? fact.option_state_audit_warnings
                    : [],
              },
            }
          : (
              fact.validator_meta ??
              result.ai_validator ??
              {}
            ),
    });
  }
}

const missingValidatedUnitIds =
  [...savedByUnitId.keys()]
    .filter(unitId => !analysisUnitIds.includes(unitId));

if (missingValidatedUnitIds.length > 0) {
  throw new Error(
    '[Собрать факты документа] Отсутствуют validated units: ' +
    missingValidatedUnitIds.join(', ')
  );
}


// ------------------------------------------------------------
// 6. OUTPUT
// ------------------------------------------------------------

return [
  {
    json: {

      analysis_run_id:
        analysisRunId,

      tender:
        firstSaved.tender ??
        validatedItems[0]?.json?.tender ??
        null,

      document:
        firstSaved.document ??
        validatedItems[0]?.json?.document ??
        null,

      analysis_summary: {

        units_expected:
          expectedUnits,

        units_received:
          validatedItems.length,

        analysis_unit_ids:
          analysisUnitIds,

        facts_count:
          facts.length,

        confirmed_count:
          confirmedCount,

        requires_review_count:
          requiresReviewCount,

        rejected_count:
          rejectedCount,
      },

      facts,
    },
  },
];

const CONFIG = {
  validatorResponseVersion: 'ai_validator_response_check_v1',

  factLocalLiteralGuardVersion: 'fact_local_material_literals_v1',

  expectedSchemaVersion: 'ai_validator_v1',

  expectedPromptVersion: 'ai_validator_prompt_v1_2',

  expectedFieldProfilesVersion: 'validator_field_profiles_v1',

  sourceNodeName: 'Развернуть units для AI Validator',

  maxReasonNoteLength: 1000,
};


// ============================================================
// 1. РАЗРЕШЁННЫЕ ЗНАЧЕНИЯ
// ============================================================

const ALLOWED_VERDICTS = new Set([
  'confirmed',
  'requires_review',
  'rejected',
]);


const ALLOWED_REASON_CODES = new Set([
  'wrong_field_classification',
  'value_not_supported',
  'overinterpretation',
  'missing_qualification',
  'insufficient_evidence',
  'conflicting_evidence',
  'source_quality_issue',
  'template_or_placeholder',
  'other',
]);


const ROOT_ALLOWED_KEYS = new Set([
  'schema_version',
  'analysis_unit_id',
  'validations',
]);


const VALIDATION_ALLOWED_KEYS = new Set([
  'fact_index',
  'field_key',
  'verdict',
  'confidence',
  'reason_code',
  'reason_note',
]);


// ============================================================
// 2. ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
// ============================================================

function fail(itemIndex, message) {
  throw new Error(
    `[Проверить ответ AI Validator] Item ${itemIndex + 1}: ${message}`
  );
}


function toDeterministicValidatedFact(candidate, unit) {
  const unitId = unit.analysis_unit_meta?.analysis_unit_id;
  if (!isObject(candidate) || !Number.isInteger(candidate.fact_index)) throw new Error('[Units without AI] Invalid deterministic rejected fact.');
  if (!Array.isArray(candidate.evidence) || candidate.evidence.length === 0) throw new Error('[Units without AI] Deterministic rejected fact has no evidence.');
  const rejectionVersion = candidate.deterministic_rejection?.version;
  const rejectionReason = candidate.deterministic_rejection?.reason_code;
  if (rejectionVersion === 'deterministic_option_applicability_v1') {
    const optionEvidence = candidate.option_state_evidence;
    if (rejectionReason !== 'unselected_option_not_applicable' || candidate.option_state_applicability !== 'excluded') throw new Error('[Units without AI] Invalid option-state rejection contract.');
    if (!Array.isArray(optionEvidence) || optionEvidence.length === 0 || optionEvidence.some((entry) => entry?.state !== 'unselected')) throw new Error('[Units without AI] Option-state rejection lacks exact unselected provenance.');
    if (!candidate.evidence.some((evidence) => evidence?.scope === 'primary')) throw new Error('[Units without AI] Option-state rejection lacks primary evidence.');
    return {
      fact_index: candidate.fact_index,
      field_key: candidate.field_key,
      value_text: candidate.value_text,
      extractor: { status: candidate.status, confidence: candidate.confidence, review_reason_code: candidate.review_reason_code, review_note: candidate.review_note },
      ai_validation: { verdict: 'rejected', confidence: 1.0, reason_code: 'unselected_option_not_applicable', reason_note: 'Rejected by deterministic DOCX option-state applicability because exact grounded option provenance proves the candidate is unselected.' },
      processing_status: 'rejected',
      accepted_for_normalization: false,
      evidence: candidate.evidence,
      option_state_applicability: 'excluded',
      option_state_evidence: optionEvidence,
      option_state_audit_warnings: Array.isArray(candidate.option_state_audit_warnings) ? candidate.option_state_audit_warnings : [],
      validator_meta: { ...(isObject(candidate.validator_meta) ? candidate.validator_meta : {}), origin: 'deterministic_option_state_layer', ai_validator_called_for_fact: false, grounding: 'exact_option_state', analysis_unit_id: unitId, fact_index: candidate.fact_index, version: rejectionVersion, validation_attempt: candidate.deterministic_rejection?.validation_attempt ?? unit.validation_attempt ?? null },
    };
  }
  if (candidate.evidence.some((evidence) => evidence?.scope !== 'overlap')) throw new Error('[Units without AI] Deterministic rejected evidence is not overlap-only.');
  const originalViolationCodes = Array.isArray(candidate.original_violations) ? candidate.original_violations.map(({ code }) => code) : [];
  if (originalViolationCodes.length !== 1 || originalViolationCodes[0] !== 'overlap_only') throw new Error('[Units without AI] Deterministic rejection is not pure overlap_only.');
  return {
    fact_index: candidate.fact_index,
    field_key: candidate.field_key,
    value_text: candidate.value_text,
    extractor: { status: candidate.status, confidence: candidate.confidence, review_reason_code: candidate.review_reason_code, review_note: candidate.review_note },
    ai_validation: { verdict: 'rejected', confidence: 1.0, reason_code: 'overlap_only_context_only', reason_note: 'Rejected by deterministic evidence validation because every exact-grounded evidence item belongs only to overlap context and no primary evidence exists.' },
    processing_status: 'rejected',
    accepted_for_normalization: false,
    evidence: candidate.evidence,
    validator_meta: { ...(isObject(candidate.validator_meta) ? candidate.validator_meta : {}), origin: 'deterministic_evidence_layer', ai_validator_called_for_fact: false, grounding: 'exact', evidence_scope: 'overlap_only', analysis_unit_id: unitId, fact_index: candidate.fact_index, version: candidate.deterministic_rejection?.version ?? 'deterministic_overlap_rejection_v1', validation_attempt: candidate.deterministic_rejection?.validation_attempt ?? unit.validation_attempt ?? null, evidence_validator_version: unit.evidence_validation?.version ?? null, original_violation_codes: originalViolationCodes },
  };
}


function isObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}


function assertNoExtraKeys(
  object,
  allowedKeys,
  itemIndex,
  path
) {
  for (const key of Object.keys(object)) {
    if (!allowedKeys.has(key)) {
      fail(
        itemIndex,
        `${path}: обнаружено недопустимое поле "${key}".`
      );
    }
  }
}


function assertString(
  value,
  itemIndex,
  path,
  {
    minLength = 1,
    maxLength = Infinity,
  } = {}
) {
  if (typeof value !== 'string') {
    fail(
      itemIndex,
      `${path}: ожидалась строка.`
    );
  }

  if (value.length < minLength) {
    fail(
      itemIndex,
      `${path}: строка слишком короткая.`
    );
  }

  if (value.length > maxLength) {
    fail(
      itemIndex,
      `${path}: превышена максимальная длина ${maxLength}.`
    );
  }
}


function parseValidatorContent(
  content,
  itemIndex
) {
  if (
    typeof content !== 'string' ||
    content.trim().length === 0
  ) {
    fail(
      itemIndex,
      'choices[0].message.content пуст.'
    );
  }

  try {
    return JSON.parse(
      content.trim()
    );
  } catch (error) {
    fail(
      itemIndex,
      `Ответ AI Validator не является валидным JSON: ${error.message}`
    );
  }
}



function normalizeUnicodeText(value) {
  return String(value ?? '')
    .normalize('NFKC')
    .replace(/[\u00a0\u202f]/g, ' ')
    .replace(/[\u2010-\u2015\u2212]/g, '-')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}


function normalizeUnicodeLines(value) {
  return String(value ?? '')
    .normalize('NFKC')
    .replace(/[\u00a0\u202f]/g, ' ')
    .replace(/[\u2010-\u2015\u2212]/g, '-')
    .split(/\r?\n/)
    .map(
      line =>
        line.replace(/[ \t]+/g, ' ').trim()
    )
    .join('\n')
    .toLowerCase();
}


function normalizeSimpleNumber(value) {
  const normalized =
    normalizeUnicodeText(value)
      .replace(/\s+/g, '')
      .replace(',', '.');

  if (!/^\d+(?:\.\d+)?$/.test(normalized)) {
    return normalized;
  }

  const [
    integerPart,
    decimalPart = '',
  ] = normalized.split('.');

  const integer =
    integerPart.replace(/^0+(?=\d)/, '');

  const decimal =
    decimalPart.replace(/0+$/, '');

  return decimal.length > 0
    ? integer + '.' + decimal
    : integer;
}


function normalizeMoneyNumber(value) {
  let normalized =
    normalizeUnicodeText(value)
      .replace(/\s+/g, '');

  const lastComma =
    normalized.lastIndexOf(',');

  const lastDot =
    normalized.lastIndexOf('.');

  if (lastComma >= 0 && lastDot >= 0) {
    const decimalSeparator =
      lastComma > lastDot ? ',' : '.';

    const thousandsSeparator =
      decimalSeparator === ',' ? '.' : ',';

    normalized =
      normalized
        .split(thousandsSeparator)
        .join('')
        .replace(decimalSeparator, '.');
  }
  else {
    const separator =
      lastComma >= 0
        ? ','
        : (
          lastDot >= 0
            ? '.'
            : null
        );

    if (separator) {
      const parts =
        normalized.split(separator);

      const decimalDigits =
        parts[parts.length - 1].length;

      if (
        parts.length > 2 ||
        decimalDigits === 3
      ) {
        normalized =
          parts.join('');
      }
      else {
        normalized =
          parts.slice(0, -1).join('') +
          '.' +
          parts[parts.length - 1];
      }
    }
  }

  return normalizeSimpleNumber(normalized);
}


function pushLiteral(
  literals,
  seen,
  {
    type,
    value,
    normalized,
  }
) {
  const key =
    type + ':' + normalized;

  if (seen.has(key)) {
    return;
  }

  seen.add(key);

  literals.push({
    type,
    value,
    normalized,
  });
}


function normalizeIdentifierKind(value) {
  const normalized =
    normalizeUnicodeText(value);

  if (normalized.startsWith('договор')) return 'договор';
  if (normalized.startsWith('контракт')) return 'контракт';
  if (normalized.startsWith('приложени')) return 'приложение';
  if (normalized.startsWith('спецификаци')) return 'спецификация';
  if (normalized.startsWith('лот')) return 'лот';
  if (normalized.startsWith('извещени')) return 'извещение';
  if (normalized.startsWith('закупк')) return 'закупка';
  if (normalized.startsWith('заявк')) return 'заявка';
  if (normalized.startsWith('пункт')) return 'пункт';
  if (normalized.startsWith('раздел')) return 'раздел';

  return normalized;
}


function normalizeIdentifierValue(value) {
  return normalizeUnicodeText(value)
    .replace(/\s+/g, '')
    .replace(/^[#№]+/, '')
    .replace(/[.,;:)\]}]+$/, '');
}


function extractMaterialLiterals(value) {
  const text =
    normalizeUnicodeText(value);

  const literals = [];
  const seen =
    new Set();


  for (
    const match
    of text.matchAll(
      /(?<![\p{L}\d])(\d+(?:[.,]\d+)?)\s*%(?!\p{L})/gu
    )
  ) {
    const number =
      normalizeSimpleNumber(match[1]);

    pushLiteral(
      literals,
      seen,
      {
        type: 'percentage',
        value: number + '%',
        normalized: number + '%',
      }
    );
  }


  for (
    const match
    of text.matchAll(
      /(?<!\d)(\d{4})[./-](\d{1,2})[./-](\d{1,2})(?!\d)/g
    )
  ) {
    const normalized =
      match[1] +
      '-' +
      match[2].padStart(2, '0') +
      '-' +
      match[3].padStart(2, '0');

    pushLiteral(
      literals,
      seen,
      {
        type: 'date',
        value: match[0],
        normalized,
      }
    );
  }


  for (
    const match
    of text.matchAll(
      /(?<!\d)(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})(?!\d)/g
    )
  ) {
    const year =
      match[3].length === 2
        ? match[3]
        : match[3];

    const normalized =
      year +
      '-' +
      match[2].padStart(2, '0') +
      '-' +
      match[1].padStart(2, '0');

    pushLiteral(
      literals,
      seen,
      {
        type: 'date',
        value: match[0],
        normalized,
      }
    );
  }


  const monthNumbers = {
    января: '01',
    февраля: '02',
    марта: '03',
    апреля: '04',
    мая: '05',
    июня: '06',
    июля: '07',
    августа: '08',
    сентября: '09',
    октября: '10',
    ноября: '11',
    декабря: '12',
  };

  for (
    const match
    of text.matchAll(
      /(?<!\d)(\d{1,2})\s+(января|февраля|марта|апреля|мая|июня|июля|августа|сентября|октября|ноября|декабря)\s+(\d{4})(?:\s*г(?:ода|\.)?)?/g
    )
  ) {
    const normalized =
      match[3] +
      '-' +
      monthNumbers[match[2]] +
      '-' +
      match[1].padStart(2, '0');

    pushLiteral(
      literals,
      seen,
      {
        type: 'date',
        value: match[0],
        normalized,
      }
    );
  }


  for (
    const match
    of text.matchAll(
      /(?<![\p{L}\d])(\d{1,3}(?:[ \u00a0\u202f]\d{3})+(?:[.,]\d{1,2})?|\d+(?:[.,]\d{1,2})?)\s*(тыс(?:\.|яч\p{L}*)?|млн\.?|миллион\p{L}*|млрд\.?|миллиард\p{L}*)?\s*(₽|руб(?:\.|л\p{L}*)?|rub|usd|доллар\p{L}*|\$|eur|евро|€)(?!\p{L})/gu
    )
  ) {
    const multiplier =
      normalizeUnicodeText(match[2] ?? '')
        .replace(/\.$/, '');

    const currencyRaw =
      normalizeUnicodeText(match[3]);

    const currency =
      /^(₽|руб|rub)/.test(currencyRaw)
        ? 'rub'
        : (
          /^(usd|доллар|\$)/.test(currencyRaw)
            ? 'usd'
            : 'eur'
        );

    const number =
      normalizeMoneyNumber(match[1]);

    const normalized =
      number +
      (multiplier ? ':' + multiplier : '') +
      ':' +
      currency;

    pushLiteral(
      literals,
      seen,
      {
        type: 'money',
        value:
          number +
          (multiplier ? ' ' + multiplier : '') +
          ' ' +
          currency,
        normalized,
      }
    );
  }


  for (
    const match
    of text.matchAll(
      /(?<![\p{L}\d])(\d+(?:[.,]\d+)?)(?:-\p{L}{1,5})?\s+((?:рабоч\p{L}*|календарн\p{L}*)\s+)?(дн\p{L}*|сут\p{L}*|месяц\p{L}*|мес\.?|год\p{L}*|лет|час\p{L}*|минут\p{L}*)(?!\p{L})/gu
    )
  ) {
    const qualifierRaw =
      normalizeUnicodeText(match[2] ?? '');

    const qualifier =
      qualifierRaw.startsWith('рабоч')
        ? 'working'
        : (
          qualifierRaw.startsWith('календар')
            ? 'calendar'
            : ''
        );

    const unitRaw =
      normalizeUnicodeText(match[3]);

    const unit =
      /^(дн|сут)/.test(unitRaw)
        ? 'day'
        : (
          /^(месяц|мес)/.test(unitRaw)
            ? 'month'
            : (
              /^(год|лет)/.test(unitRaw)
                ? 'year'
                : (
                  unitRaw.startsWith('час')
                    ? 'hour'
                    : 'minute'
                )
            )
        );

    const number =
      normalizeSimpleNumber(match[1]);

    const normalized =
      number +
      ':' +
      qualifier +
      ':' +
      unit;

    pushLiteral(
      literals,
      seen,
      {
        type: 'duration',
        value:
          number +
          ' ' +
          (qualifier ? qualifier + ' ' : '') +
          unit,
        normalized,
      }
    );
  }


  for (
    const match
    of text.matchAll(
      /((?:договор|контракт|приложени|спецификаци|лот|извещени|закупк|заявк|пункт|раздел)\p{L}*)\s*(?:№|n(?:o)?\.?|номер)\s*([a-zа-яё0-9][a-zа-яё0-9./_-]*)/gu
    )
  ) {
    const kind =
      normalizeIdentifierKind(match[1]);

    const identifier =
      normalizeIdentifierValue(match[2]);

    const normalized =
      kind +
      ':' +
      identifier;

    pushLiteral(
      literals,
      seen,
      {
        type: 'identifier',
        value:
          kind +
          ' № ' +
          identifier,
        normalized,
      }
    );
  }


  return literals;
}



function extractFactLocalTableMoneyLiterals(evidenceItems) {
  if (!Array.isArray(evidenceItems)) {
    return [];
  }

  const tableEvidence =
    evidenceItems.filter(
      evidence =>
        evidence?.type === 'table' &&
        typeof evidence?.semantic_block_id === 'string' &&
        typeof evidence?.quote === 'string'
    );

  const unitByBlockAndColumn =
    new Map();


  for (const evidence of tableEvidence) {
    const text =
      normalizeUnicodeLines(
        evidence.quote
      );

    for (
      const match
      of text.matchAll(
        /\[c(\d+)\][^\n]*(тыс(?:\.|яч\p{L}*)?|млн\.?|миллион\p{L}*|млрд\.?|миллиард\p{L}*)\s*(₽|руб(?:\.|л\p{L}*)?|rub|usd|доллар\p{L}*|\$|eur|евро|€)/gu
      )
    ) {
      const multiplier =
        normalizeUnicodeText(match[2])
          .replace(/\.$/, '');

      const currencyRaw =
        normalizeUnicodeText(match[3]);

      const currency =
        /^(₽|руб|rub)/.test(currencyRaw)
          ? 'rub'
          : (
            /^(usd|доллар|\$)/.test(currencyRaw)
              ? 'usd'
              : 'eur'
          );

      unitByBlockAndColumn.set(
        evidence.semantic_block_id +
        ':c' +
        match[1],
        {
          multiplier,
          currency,
        }
      );
    }
  }


  const literals = [];
  const seen =
    new Set();


  for (const evidence of tableEvidence) {
    const text =
      normalizeUnicodeLines(
        evidence.quote
      );

    for (
      const match
      of text.matchAll(
        /\[c(\d+)\]\s*(\d+(?:[.,]\d+)?)\s*(?=\n|$)/g
      )
    ) {
      const unit =
        unitByBlockAndColumn.get(
          evidence.semantic_block_id +
          ':c' +
          match[1]
        );

      if (!unit) {
        continue;
      }

      const number =
        normalizeMoneyNumber(match[2]);

      const normalized =
        number +
        ':' +
        unit.multiplier +
        ':' +
        unit.currency;

      pushLiteral(
        literals,
        seen,
        {
          type: 'money',
          value:
            number +
            ' ' +
            unit.multiplier +
            ' ' +
            unit.currency,
          normalized,
        }
      );
    }
  }


  return literals;
}


function assessFactLocalMaterialLiterals(fact) {
  const valueLiterals =
    extractMaterialLiterals(
      fact?.value_text
    );

  const factEvidenceText =
    Array.isArray(fact?.evidence)
      ? fact.evidence
          .map(
            evidence =>
              typeof evidence?.quote === 'string'
                ? evidence.quote
                : ''
          )
          .join('\n')
      : '';

  const factEvidenceLiterals = [
    ...extractMaterialLiterals(
      factEvidenceText
    ),
    ...extractFactLocalTableMoneyLiterals(
      fact?.evidence
    ),
  ];


  const evidenceKeys =
    new Set(
      factEvidenceLiterals.map(
        literal =>
          literal.type +
          ':' +
          literal.normalized
      )
    );

  const missingLiterals =
    valueLiterals.filter(
      literal =>
        !evidenceKeys.has(
          literal.type +
          ':' +
          literal.normalized
        )
    );

  return {
    missing_literals:
      missingLiterals,
  };
}


// ============================================================
// 3. INPUT
// ============================================================

const validatorItems =
  $input.all();

const sourceItems =
  $(CONFIG.sourceNodeName).all();


if (validatorItems.length === 0) {
  throw new Error(
    '[Проверить ответ AI Validator] Нет входных items.'
  );
}


if (
  validatorItems.length !==
  sourceItems.length
) {
  throw new Error(
    `[Проверить ответ AI Validator] Количество items не совпадает: ` +
    `AI Validator=${validatorItems.length}, ` +
    `${CONFIG.sourceNodeName}=${sourceItems.length}.`
  );
}


// ============================================================
// 4. ОБРАБОТКА КАЖДОГО ITEM
// ============================================================

return validatorItems.map(
  (
    validatorItem,
    itemIndex
  ) => {
    const apiResponse =
      validatorItem?.json;

    const source =
      $(CONFIG.sourceNodeName)
        .itemMatching(itemIndex)
        ?.json;


    // --------------------------------------------------------
    // Проверяем входные данные
    // --------------------------------------------------------

    if (!isObject(apiResponse)) {
      fail(
        itemIndex,
        'Некорректный ответ HTTP Request AI Validator.'
      );
    }


    if (!isObject(source)) {
      fail(
        itemIndex,
        `Не удалось получить данные из ноды "${CONFIG.sourceNodeName}".`
      );
    }


    if (
      source.evidence_validation?.passed !== true
    ) {
      fail(
        itemIndex,
        'Входные facts не прошли предыдущую evidence validation.'
      );
    }


    if (
      !Array.isArray(
        source.verified_facts
      )
    ) {
      fail(
        itemIndex,
        'verified_facts отсутствует.'
      );
    }


    const promptContext =
      source.validator_prompt_context;


    if (!isObject(promptContext)) {
      fail(
        itemIndex,
        'validator_prompt_context отсутствует.'
      );
    }


    if (
      promptContext.prompt_version !==
      CONFIG.expectedPromptVersion
    ) {
      fail(
        itemIndex,
        `Неверный validator prompt version: "${promptContext.prompt_version}".`
      );
    }


    if (
      promptContext.field_profiles_version !==
      CONFIG.expectedFieldProfilesVersion
    ) {
      fail(
        itemIndex,
        `Неверный field profiles version: "${promptContext.field_profiles_version}".`
      );
    }


    if (
      !Array.isArray(promptContext.field_keys) ||
      promptContext.field_keys.length === 0
    ) {
      fail(
        itemIndex,
        'validator_prompt_context.field_keys отсутствует или пуст.'
      );
    }


    if (
      typeof promptContext.field_profiles_text !== 'string' ||
      promptContext.field_profiles_text.length === 0
    ) {
      fail(
        itemIndex,
        'validator_prompt_context.field_profiles_text отсутствует или пуст.'
      );
    }


    // --------------------------------------------------------
    // Проверяем HTTP-ответ AI Validator
    // --------------------------------------------------------

    if (
      !Array.isArray(
        apiResponse.choices
      ) ||
      apiResponse.choices.length === 0
    ) {
      fail(
        itemIndex,
        'AI Validator не вернул choices.'
      );
    }


    const choice =
      apiResponse.choices[0];


    if (!isObject(choice)) {
      fail(
        itemIndex,
        'choices[0] имеет неверный формат.'
      );
    }


    if (
      choice.finish_reason !== 'stop'
    ) {
      fail(
        itemIndex,
        `AI Validator завершил ответ с finish_reason="${choice.finish_reason}".`
      );
    }


    if (!isObject(choice.message)) {
      fail(
        itemIndex,
        'choices[0].message отсутствует.'
      );
    }


    // --------------------------------------------------------
    // Парсим JSON второго AI
    // --------------------------------------------------------

    const parsed =
      parseValidatorContent(
        choice.message.content,
        itemIndex
      );


    if (!isObject(parsed)) {
      fail(
        itemIndex,
        'Корневой JSON AI Validator должен быть объектом.'
      );
    }


    // ========================================================
    // 5. ROOT VALIDATION
    // ========================================================

    assertNoExtraKeys(
      parsed,
      ROOT_ALLOWED_KEYS,
      itemIndex,
      'AIValidatorV1'
    );


    if (
      parsed.schema_version !==
      CONFIG.expectedSchemaVersion
    ) {
      fail(
        itemIndex,
        `Неверный schema_version: "${parsed.schema_version}".`
      );
    }


    const expectedAnalysisUnitId =
      source.analysis_unit_meta
        ?.analysis_unit_id;


    assertString(
      expectedAnalysisUnitId,
      itemIndex,
      'analysis_unit_meta.analysis_unit_id'
    );


    if (
      parsed.analysis_unit_id !==
      expectedAnalysisUnitId
    ) {
      fail(
        itemIndex,
        `analysis_unit_id не совпадает. ` +
        `Ожидался "${expectedAnalysisUnitId}", ` +
        `получен "${parsed.analysis_unit_id}".`
      );
    }


    if (
      !Array.isArray(
        parsed.validations
      )
    ) {
      fail(
        itemIndex,
        'validations должен быть массивом.'
      );
    }


    // ========================================================
    // 6. ПРОВЕРЯЕМ SOURCE FACTS
    // ========================================================

    const sourceFacts =
      source.verified_facts;


    const sourceFactMap =
      new Map();


    for (
      let sourceIndex = 0;
      sourceIndex < sourceFacts.length;
      sourceIndex++
    ) {
      const fact =
        sourceFacts[sourceIndex];


      if (!isObject(fact)) {
        fail(
          itemIndex,
          `verified_facts[${sourceIndex}] имеет неверный формат.`
        );
      }


      if (
        !Number.isInteger(
          fact.fact_index
        )
      ) {
        fail(
          itemIndex,
          `verified_facts[${sourceIndex}].fact_index должен быть целым числом.`
        );
      }


      if (
        sourceFactMap.has(
          fact.fact_index
        )
      ) {
        fail(
          itemIndex,
          `В verified_facts повторяется fact_index=${fact.fact_index}.`
        );
      }


      assertString(
        fact.field_key,
        itemIndex,
        `verified_facts[${sourceIndex}].field_key`
      );


      sourceFactMap.set(
        fact.fact_index,
        fact
      );
    }


    const sourceFieldKeys =
      new Set(
        sourceFacts.map(
          fact => fact.field_key
        )
      );


    if (
      new Set(promptContext.field_keys).size !==
      promptContext.field_keys.length
    ) {
      fail(
        itemIndex,
        'validator_prompt_context.field_keys содержит дубликаты.'
      );
    }


    if (
      promptContext.field_keys.length !== sourceFieldKeys.size ||
      promptContext.field_keys.some(
        fieldKey => !sourceFieldKeys.has(fieldKey)
      )
    ) {
      fail(
        itemIndex,
        'validator_prompt_context.field_keys не соответствует verified_facts.'
      );
    }


    if (
      !Array.isArray(source.validator_field_keys) ||
      JSON.stringify(source.validator_field_keys) !==
      JSON.stringify(promptContext.field_keys)
    ) {
      fail(
        itemIndex,
        'validator_field_keys не соответствует validator_prompt_context.field_keys.'
      );
    }


    // --------------------------------------------------------
    // Количество validations обязано совпадать
    // --------------------------------------------------------

    if (
      parsed.validations.length !==
      sourceFacts.length
    ) {
      fail(
        itemIndex,
        `AI Validator должен вернуть ровно одну validation на каждый fact. ` +
        `Ожидалось ${sourceFacts.length}, ` +
        `получено ${parsed.validations.length}.`
      );
    }


    // ========================================================
    // 7. ПРОВЕРЯЕМ КАЖДУЮ VALIDATION
    // ========================================================

    const validationMap =
      new Map();


    parsed.validations.forEach(
      (
        validation,
        validationIndex
      ) => {
        const path =
          `validations[${validationIndex}]`;


        if (!isObject(validation)) {
          fail(
            itemIndex,
            `${path}: validation должен быть объектом.`
          );
        }


        assertNoExtraKeys(
          validation,
          VALIDATION_ALLOWED_KEYS,
          itemIndex,
          path
        );


        // ----------------------------------------------------
        // fact_index
        // ----------------------------------------------------

        if (
          !Number.isInteger(
            validation.fact_index
          )
        ) {
          fail(
            itemIndex,
            `${path}.fact_index должен быть целым числом.`
          );
        }


        if (
          validationMap.has(
            validation.fact_index
          )
        ) {
          fail(
            itemIndex,
            `${path}: fact_index=${validation.fact_index} повторяется.`
          );
        }


        const originalFact =
          sourceFactMap.get(
            validation.fact_index
          );


        if (!originalFact) {
          fail(
            itemIndex,
            `${path}: AI Validator добавил неизвестный fact_index=${validation.fact_index}.`
          );
        }


        // ----------------------------------------------------
        // field_key
        // ----------------------------------------------------

        assertString(
          validation.field_key,
          itemIndex,
          `${path}.field_key`
        );


        if (
          validation.field_key !==
          originalFact.field_key
        ) {
          fail(
            itemIndex,
            `${path}: AI Validator изменил field_key. ` +
            `Для fact_index=${validation.fact_index} ` +
            `ожидался "${originalFact.field_key}", ` +
            `получен "${validation.field_key}".`
          );
        }


        // ----------------------------------------------------
        // verdict
        // ----------------------------------------------------

        if (
          !ALLOWED_VERDICTS.has(
            validation.verdict
          )
        ) {
          fail(
            itemIndex,
            `${path}: недопустимый verdict "${validation.verdict}".`
          );
        }


        // ----------------------------------------------------
        // confidence
        // ----------------------------------------------------

        if (
          typeof validation.confidence !== 'number' ||
          !Number.isFinite(
            validation.confidence
          ) ||
          validation.confidence < 0 ||
          validation.confidence > 1
        ) {
          fail(
            itemIndex,
            `${path}.confidence должен быть числом от 0 до 1.`
          );
        }


        // ----------------------------------------------------
        // reason_code / reason_note
        // ----------------------------------------------------

        if (
          validation.verdict ===
          'confirmed'
        ) {
          if (
            validation.reason_code !== null
          ) {
            fail(
              itemIndex,
              `${path}: для verdict=confirmed reason_code должен быть null.`
            );
          }


          if (
            validation.reason_note !== null
          ) {
            fail(
              itemIndex,
              `${path}: для verdict=confirmed reason_note должен быть null.`
            );
          }
        }


        if (
          validation.verdict ===
            'requires_review' ||
          validation.verdict ===
            'rejected'
        ) {
          if (
            !ALLOWED_REASON_CODES.has(
              validation.reason_code
            )
          ) {
            fail(
              itemIndex,
              `${path}: для verdict=${validation.verdict} ` +
              `нужен допустимый reason_code. Получено "${validation.reason_code}".`
            );
          }


          if (
            validation.reason_note !== null
          ) {
            assertString(
              validation.reason_note,
              itemIndex,
              `${path}.reason_note`,
              {
                minLength: 1,
                maxLength:
                  CONFIG.maxReasonNoteLength,
              }
            );
          }
        }


        validationMap.set(
          validation.fact_index,
          validation
        );
      }
    );


    // ========================================================
    // 8. ПРОВЕРЯЕМ, ЧТО НЕ ПРОПУЩЕН НИ ОДИН FACT
    // ========================================================

    for (
      const fact
      of sourceFacts
    ) {
      if (
        !validationMap.has(
          fact.fact_index
        )
      ) {
        fail(
          itemIndex,
          `AI Validator пропустил fact_index=${fact.fact_index}.`
        );
      }
    }


    // ========================================================
    // 9. ОБЪЕДИНЯЕМ EXTRACTOR + VALIDATOR
    // ========================================================

    const aiValidatedFacts =
      sourceFacts.map(
        fact => {
          const validation =
            validationMap.get(
              fact.fact_index
            );


          const optionStateReviewOnly =
            fact.option_state_applicability ===
            'review_only';


          const literalGuardApplied =
            validation.verdict ===
            'confirmed' &&
            !optionStateReviewOnly;


          const literalGuardResult =
            literalGuardApplied
              ? assessFactLocalMaterialLiterals(fact)
              : { missing_literals: [] };


          const literalGuardDowngraded =
            literalGuardApplied &&
            literalGuardResult.missing_literals.length > 0;


          const effectiveVerdict =
            optionStateReviewOnly ||
            literalGuardDowngraded
              ? 'requires_review'
              : validation.verdict;


          const effectiveReasonCode =
            optionStateReviewOnly
              ? 'source_quality_issue'
              : (
                  literalGuardDowngraded
                    ? 'insufficient_evidence'
                    : validation.reason_code
                );


          const effectiveReasonNote =
