                mapping_warnings: warnings,
              });
            }
          });
          scan(table);
        }
      } else {
        for (const value of values) scan(value);
      }
    }
  }
  scan(documentJson);
  return records;
}

function relationships(partJson) {
  const root = firstDescendant({ root: partJson }, 'Relationships');
  if (!root) return [];
  return childValues(root, 'Relationship').map((relationship) => ({
    id: attr(relationship, 'Id'),
    type: attr(relationship, 'Type'),
    target: attr(relationship, 'Target'),
    targetMode: attr(relationship, 'TargetMode'),
  }));
}

function resolvePart(sourcePart, target) {
  const raw = String(target ?? '').replace(/\\/gu, '/');
  if (!raw || raw.startsWith('/') || /^[a-z][a-z0-9+.-]*:/iu.test(raw)) return null;
  const base = sourcePart.split('/').slice(0, -1);
  for (const segment of raw.split('/')) {
    if (!segment || segment === '.') continue;
    if (segment === '..') {
      if (!base.length) return null;
      base.pop();
    } else {
      base.push(segment);
    }
  }
  return base.join('/');
}

function relationshipPart(sourcePart) {
  const segments = sourcePart.split('/');
  const fileName = segments.pop();
  return [...segments, '_rels', fileName + '.rels'].join('/');
}

function ensureRange(buffer, offset, length, code = 'malformed_cfb') {
  if (!Number.isSafeInteger(offset) || !Number.isSafeInteger(length) || offset < 0 || length < 0 || offset + length > buffer.length) {
    fail(code, 'Binary structure references bytes outside the available buffer');
  }
}

function decodeDirectoryName(buffer, offset) {
  const byteLength = buffer.readUInt16LE(offset + 64);
  if (byteLength < 2 || byteLength > 64 || byteLength % 2 !== 0) return '';
  return buffer.subarray(offset, offset + byteLength - 2).toString('utf16le');
}

function readCfbContents(buffer) {
  if (!Buffer.isBuffer(buffer) || buffer.length < 512 || buffer.length > MAX_CFB_BYTES) fail('malformed_cfb', 'ActiveX persistence is not a bounded CFB file');
  if (!buffer.subarray(0, 8).equals(Buffer.from('d0cf11e0a1b11ae1', 'hex'))) fail('malformed_cfb', 'CFB signature is missing');
  const majorVersion = buffer.readUInt16LE(26);
  const byteOrder = buffer.readUInt16LE(28);
  const sectorShift = buffer.readUInt16LE(30);
  const miniSectorShift = buffer.readUInt16LE(32);
  const versionMatchesSectorSize = (majorVersion === 3 && sectorShift === 9) || (majorVersion === 4 && sectorShift === 12);
  if (byteOrder !== 0xfffe || !versionMatchesSectorSize || miniSectorShift !== 6) fail('unsupported_sector_size', 'Unsupported CFB version, byte order, or sector size');
  const sectorSize = 2 ** sectorShift;
  const miniSectorSize = 2 ** miniSectorShift;
  if (buffer.length < sectorSize * 2 || buffer.length % sectorSize !== 0) fail('malformed_cfb', 'CFB sector layout is truncated or misaligned');
  const sectorCount = (buffer.length - sectorSize) / sectorSize;
  const sectorOffset = (index) => {
    if (!Number.isInteger(index) || index < 0 || index >= sectorCount) fail('cfb_sector_out_of_range', 'CFB sector index is out of range');
    return sectorSize + (index * sectorSize);
  };
  const sector = (index) => buffer.subarray(sectorOffset(index), sectorOffset(index) + sectorSize);
  const numFatSectors = buffer.readUInt32LE(44);
  const firstDirectorySector = buffer.readUInt32LE(48);
  const miniStreamCutoff = buffer.readUInt32LE(56);
  const firstMiniFatSector = buffer.readUInt32LE(60);
  const numMiniFatSectors = buffer.readUInt32LE(64);
  const firstDifatSector = buffer.readUInt32LE(68);
  const numDifatSectors = buffer.readUInt32LE(72);
  if (numFatSectors < 1 || numFatSectors > MAX_FAT_SECTORS) fail('cfb_chain_limit_exceeded', 'CFB FAT sector count exceeds the safety limit');
  if (numMiniFatSectors > MAX_CHAIN_LENGTH || numDifatSectors > MAX_CHAIN_LENGTH) fail('cfb_chain_limit_exceeded', 'CFB auxiliary chain count exceeds the safety limit');
  if (miniStreamCutoff !== 4096) fail('malformed_cfb', 'Unsupported CFB mini stream cutoff');

  const fatSectorIndexes = [];
  for (let offset = 76; offset < 512 && fatSectorIndexes.length < numFatSectors; offset += 4) {
    const index = buffer.readUInt32LE(offset);
    if (index !== FREE) fatSectorIndexes.push(index);
  }
  let difatIndex = firstDifatSector;
  const difatSeen = new Set();
  for (let count = 0; fatSectorIndexes.length < numFatSectors; count += 1) {
    if (count >= numDifatSectors || count >= MAX_CHAIN_LENGTH) fail('cfb_chain_limit_exceeded', 'CFB DIFAT chain is incomplete or too long');
    if (difatSeen.has(difatIndex)) fail('cfb_chain_cycle', 'CFB DIFAT chain contains a cycle');
    difatSeen.add(difatIndex);
    const data = sector(difatIndex);
    for (let offset = 0; offset < sectorSize - 4 && fatSectorIndexes.length < numFatSectors; offset += 4) {
      const index = data.readUInt32LE(offset);
      if (index !== FREE) fatSectorIndexes.push(index);
    }
    difatIndex = data.readUInt32LE(sectorSize - 4);
  }
  if (fatSectorIndexes.length !== numFatSectors) fail('malformed_cfb', 'CFB FAT sector inventory is inconsistent');
  const fat = [];
  for (const fatSectorIndex of fatSectorIndexes) {
    const data = sector(fatSectorIndex);
    for (let offset = 0; offset < sectorSize; offset += 4) fat.push(data.readUInt32LE(offset));
  }

  function chainIndexes(start, table, label, declaredLimit = MAX_CHAIN_LENGTH) {
    if (start === END) return [];
    const indexes = [];
    const seen = new Set();
    let current = start;
    while (current !== END) {
      if (indexes.length >= declaredLimit || indexes.length >= MAX_CHAIN_LENGTH) fail('cfb_chain_limit_exceeded', 'CFB ' + label + ' chain exceeds the safety limit');
      if (!Number.isInteger(current) || current < 0 || current >= table.length || current === FREE) fail('cfb_sector_out_of_range', 'CFB ' + label + ' chain references an invalid sector');
      if (seen.has(current)) fail('cfb_chain_cycle', 'CFB ' + label + ' chain contains a cycle');
      seen.add(current);
      indexes.push(current);
      current = table[current];
    }
    return indexes;
  }

  const directoryIndexes = chainIndexes(firstDirectorySector, fat, 'directory');
  const directory = Buffer.concat(directoryIndexes.map(sector));
  const entries = [];
  for (let offset = 0; offset + 128 <= directory.length; offset += 128) {
    entries.push({
      index: offset / 128,
      name: decodeDirectoryName(directory, offset),
      type: directory[offset + 66],
      left: directory.readUInt32LE(offset + 68),
      right: directory.readUInt32LE(offset + 72),
      child: directory.readUInt32LE(offset + 76),
      start: directory.readUInt32LE(offset + 116),
      size: Number(directory.readBigUInt64LE(offset + 120)),
    });
  }
  const roots = entries.filter(({ type }) => type === 5);
  if (roots.length !== 1) fail('malformed_cfb', 'CFB must contain exactly one root directory entry');
  const root = roots[0];
  if (root.left !== FREE || root.right !== FREE) fail('cfb_directory_entry_out_of_range', 'CFB root sibling pointers must be NOSTREAM');
  const reachableEntries = [];
  const directorySeen = new Set();
  function visitDirectoryTree(index) {
    if (index === FREE) return;
    if (!Number.isInteger(index) || index < 0 || index >= entries.length) fail('cfb_directory_entry_out_of_range', 'CFB directory tree index is out of range');
    if (directorySeen.has(index)) fail('cfb_directory_tree_cycle', 'CFB directory tree contains a cycle');
    if (directorySeen.size >= MAX_CHAIN_LENGTH) fail('cfb_chain_limit_exceeded', 'CFB directory tree exceeds the safety limit');
    directorySeen.add(index);
    const entry = entries[index];
    if (entry.type !== 1 && entry.type !== 2) fail('malformed_cfb', 'CFB directory tree references an unsupported entry type');
    visitDirectoryTree(entry.left);
    reachableEntries.push(entry);
    if (entry.type === 1) visitDirectoryTree(entry.child);
    visitDirectoryTree(entry.right);
  }
  visitDirectoryTree(root.child);
  const contentsEntries = reachableEntries.filter(({ type, name }) => type === 2 && name.toLowerCase() === 'contents');
  if (contentsEntries.length === 0) fail('missing_reachable_contents', 'CFB has no reachable contents stream below Root Entry');
  if (contentsEntries.length !== 1) fail('malformed_cfb', 'CFB has multiple reachable contents streams');
  const contentsEntry = contentsEntries[0];
  if (!Number.isSafeInteger(root.size) || root.size < 0 || root.size > MAX_CFB_BYTES) fail('malformed_cfb', 'CFB root mini stream size is invalid');
  if (!Number.isSafeInteger(contentsEntry.size) || contentsEntry.size < 0) fail('malformed_cfb', 'CFB contents stream size is invalid');
  if (contentsEntry.size > MAX_CONTENTS_BYTES) fail('contents_stream_too_large', 'CFB contents stream exceeds the safety limit');

  const miniFatIndexes = numMiniFatSectors === 0
    ? []
    : chainIndexes(firstMiniFatSector, fat, 'miniFAT', numMiniFatSectors);
  if (miniFatIndexes.length !== numMiniFatSectors) fail('malformed_cfb', 'CFB miniFAT declared length is inconsistent');
  const miniFat = [];
  for (const index of miniFatIndexes) {
    const data = sector(index);
    for (let offset = 0; offset < sectorSize; offset += 4) miniFat.push(data.readUInt32LE(offset));
  }
  const rootIndexes = root.size === 0 ? [] : chainIndexes(root.start, fat, 'root mini stream');
  const miniStream = Buffer.concat(rootIndexes.map(sector)).subarray(0, root.size);

  if (contentsEntry.size < miniStreamCutoff) {
    const needed = Math.ceil(contentsEntry.size / miniSectorSize);
    const indexes = chainIndexes(contentsEntry.start, miniFat, 'contents mini stream', Math.max(needed + 1, 1));
    if (indexes.length !== needed) fail('malformed_cfb', 'CFB contents mini stream length is inconsistent');
    const chunks = indexes.map((index) => {
      const offset = index * miniSectorSize;
      ensureRange(miniStream, offset, miniSectorSize, 'cfb_sector_out_of_range');
      return miniStream.subarray(offset, offset + miniSectorSize);
    });
    return Buffer.concat(chunks).subarray(0, contentsEntry.size);
  }
  const needed = Math.ceil(contentsEntry.size / sectorSize);
  const indexes = chainIndexes(contentsEntry.start, fat, 'contents stream', Math.max(needed + 1, 1));
  if (indexes.length !== needed) fail('malformed_cfb', 'CFB contents stream length is inconsistent');
  return Buffer.concat(indexes.map(sector)).subarray(0, contentsEntry.size);
}

function align4(value) {
  return (value + 3) & ~3;
}

function decodeFmString(buffer, descriptor, cursor) {
  const compressed = (descriptor & 0x80000000) !== 0;
  const length = descriptor & 0x7fffffff;
  if (length > 65536) fail('malformed_msoforms', 'MS-OFORMS string exceeds the safety limit');
  const byteLength = compressed ? length : length * 2;
  ensureRange(buffer, cursor, byteLength, 'malformed_msoforms');
  const value = buffer.subarray(cursor, cursor + byteLength).toString(compressed ? 'latin1' : 'utf16le');
  return { value, cursor: cursor + byteLength };
}

function readMorphData(contents, expectedType) {
  ensureRange(contents, 0, 12, 'malformed_msoforms');
  if (contents[0] !== 0 || contents[1] !== 2) fail('malformed_msoforms', 'Unsupported MS-OFORMS MorphData version');
  const cbMorphData = contents.readUInt16LE(2);
  const morphEnd = 4 + cbMorphData;
  ensureRange(contents, 0, morphEnd, 'malformed_msoforms');
  const mask = contents.readBigUInt64LE(4);
  const allowedBits = [0n, 1n, 2n, 6n, 8n, 22n, 31n, 32n];
  let allowedMask = 0n;
  for (const bit of allowedBits) allowedMask |= 1n << bit;
  if ((mask & ~allowedMask) !== 0n) fail('unsupported_msoforms_properties', 'MS-OFORMS property mask contains unsupported fields');
  const has = (bit) => (mask & (1n << BigInt(bit))) !== 0n;
  let cursor = 12;
  for (const bit of [0, 1, 2]) {
    if (has(bit)) {
      ensureRange(contents, cursor, 4, 'malformed_msoforms');
      cursor += 4;
    }
  }
  let displayStyle = null;
  if (has(6)) {
    ensureRange(contents, cursor, 1, 'malformed_msoforms');
    displayStyle = contents[cursor];
    cursor += 1;
  }
  cursor = align4(cursor);
  let valueDescriptor = null;
  if (has(22)) {
    ensureRange(contents, cursor, 4, 'malformed_msoforms');
    valueDescriptor = contents.readUInt32LE(cursor);
    cursor += 4;
  }
  let groupDescriptor = null;
  if (has(32)) {
    ensureRange(contents, cursor, 4, 'malformed_msoforms');
    groupDescriptor = contents.readUInt32LE(cursor);
    cursor += 4;
  }
  cursor = align4(cursor);
  if (!has(8) || !has(31)) fail('malformed_msoforms', 'MS-OFORMS required size or reserved property is absent');
  ensureRange(contents, cursor, 8, 'malformed_msoforms');
  cursor += 8;
  if (valueDescriptor === null) fail('missing_value', 'MS-OFORMS Value property is absent');
  const decodedValue = decodeFmString(contents, valueDescriptor, cursor);
  cursor = decodedValue.cursor;
  let groupName = null;
  if (groupDescriptor !== null) {
    cursor = align4(cursor);
    const decodedGroup = decodeFmString(contents, groupDescriptor, cursor);
    groupName = decodedGroup.value;
  }
  const expectedDisplayStyle = expectedType === 'checkbox' ? 4 : 5;
  if (displayStyle !== expectedDisplayStyle) fail('unsupported_control_encoding', 'MS-OFORMS display style does not match the ActiveX class');
  if (decodedValue.value === '1') return { state: 'selected', rawValue: '1', groupName };
  if (decodedValue.value === '0') return { state: 'unselected', rawValue: '0', groupName };
  return { state: 'indeterminate', rawValue: decodedValue.value, groupName };
}

const items = $input.all();
const partItems = new Map();
const sourceWarnings = [];
items.forEach((item, index) => {
  const partPath = item.json?.docx_part_path;
  if (partPath) {
    if (partItems.has(partPath)) sourceWarnings.push(warning('duplicate_part_path', 'Multiple extracted items have the same OPC part path', { partPath }));
    else partItems.set(partPath, { item, index });
  }
  for (const sourceWarning of item.json?.docx_option_state_source_warnings ?? []) sourceWarnings.push(sourceWarning);
});

const documentItem = partItems.get(DOCUMENT_PART)?.item;
const documentRelsItem = partItems.get(DOCUMENT_RELS_PART)?.item;
if (!documentItem || documentItem.json?.docx_part_kind !== 'structured_xml' || !documentRelsItem) {
  sourceWarnings.push(warning('missing_required_ooxml_parts', 'Structured document or relationship part is unavailable'));
  return [{ json: { docx_option_state_status: 'unknown', docx_option_states: [], docx_option_state_audit: { contract_version: 'docx_option_state_audit_v1', warnings: sourceWarnings } } }];
}

const documentRelationships = relationships(documentRelsItem.json);
const controls = controlsFromDocument(documentItem.json);
const states = [];
for (const control of controls) {
  const record = {
    contract_version: CONTRACT_VERSION,
    document_part: DOCUMENT_PART,
    control_name: control.control_name,
    control_type: null,
    state: 'unknown',
    raw_value: null,
    exact_label: control.exact_label,
    group_context: null,
    source_row_ref: control.source_row_ref,
    control_rel_target: null,
    binary_rel_target: null,
    warnings: [...control.mapping_warnings],
  };
  const matchingDocumentRels = documentRelationships.filter((relationship) => relationship.id === control.document_rel_id && relationship.type === CONTROL_REL_TYPE && relationship.targetMode !== 'External');
  if (matchingDocumentRels.length !== 1) {
    record.warnings.push(warning('missing_document_relationship', 'Control does not map to exactly one internal document relationship'));
    states.push(record);
    continue;
  }
  const controlPart = resolvePart(DOCUMENT_PART, matchingDocumentRels[0].target);
  record.control_rel_target = controlPart;
  if (!controlPart) {
    record.warnings.push(warning('invalid_relationship_target', 'Document control relationship target is invalid'));
    states.push(record);
    continue;
  }
  const controlPartItem = partItems.get(controlPart)?.item;
  const ocx = controlPartItem ? firstDescendant({ root: controlPartItem.json }, 'ocx') : null;
  if (!ocx) {
    record.warnings.push(warning('missing_activex_part', 'ActiveX XML part is unavailable'));
    states.push(record);
    continue;
  }
  const classId = String(attr(ocx, 'classid') ?? '').toUpperCase();
  record.control_type = CLASS_IDS[classId] ?? 'unsupported';
  if (record.control_type === 'unsupported') {
    record.warnings.push(warning('unsupported_control_class', 'ActiveX CLSID is not a supported option-state control'));
    states.push(record);
    continue;
  }
  if (attr(ocx, 'persistence') !== 'persistStorage') {
    record.warnings.push(warning('unsupported_persistence', 'ActiveX persistence mode is not persistStorage'));
    states.push(record);
    continue;
  }
  const binaryRelId = attr(ocx, 'id');
  const relsPart = relationshipPart(controlPart);
  const activeRelsItem = partItems.get(relsPart)?.item;
  const activeRelationships = activeRelsItem ? relationships(activeRelsItem.json) : [];
  const matchingBinaryRels = activeRelationships.filter((relationship) => relationship.id === binaryRelId && relationship.type === BINARY_REL_TYPE && relationship.targetMode !== 'External');
  if (matchingBinaryRels.length !== 1) {
    record.warnings.push(warning('missing_activex_relationship', 'ActiveX XML does not map to exactly one internal persistence relationship'));
    states.push(record);
    continue;
  }
  const binaryPart = resolvePart(controlPart, matchingBinaryRels[0].target);
  record.binary_rel_target = binaryPart;
  const binaryEntry = binaryPart ? partItems.get(binaryPart) : null;
  if (!binaryEntry?.item?.binary?.data) {
    record.warnings.push(warning('missing_activex_binary', 'ActiveX persistence binary part is unavailable'));
    states.push(record);
    continue;
  }
  try {
    const binaryBuffer = await this.helpers.getBinaryDataBuffer(binaryEntry.index, 'data');
    const decoded = readMorphData(readCfbContents(binaryBuffer), record.control_type);
    record.raw_value = decoded.rawValue;
    record.group_context = decoded.groupName;
    if (record.warnings.length === 0) {
      record.state = decoded.state;
      if (decoded.state === 'indeterminate') record.warnings.push(warning('indeterminate_value', 'MS-OFORMS Value is neither 0 nor 1'));
    }
  } catch (error) {
    const code = error?.optionStateCode ?? 'malformed_activex_persistence';
    record.warnings.push(warning(code, String(error?.message ?? 'ActiveX persistence decoding failed')));
  }
  states.push(record);
}

const resolvedCount = states.filter(({ state }) => state === 'selected' || state === 'unselected').length;
const status = sourceWarnings.length > 0 || states.length === 0
  ? 'unknown'
  : resolvedCount === states.length ? 'resolved' : resolvedCount > 0 ? 'partial' : 'unknown';
return [{
  json: {
    docx_option_state_status: status,
    docx_option_states: states,
    docx_option_state_audit: {
      contract_version: 'docx_option_state_audit_v1',
      controls_count: states.length,
      resolved_count: resolvedCount,
      warnings: sourceWarnings,
    },
  },
}];
